    {"id": "S04", "voice": "박도윤", "expect": "status", "pause": 0.56, "raw": "하나야 5번 압축기 상태 알려 줘"},
    {"id": "S05", "voice": "김하늘", "expect": "record", "pause": 0.15, "raw": "하나에 5번 압축기 정지 기록해 줘"},
    {"id": "S06", "voice": "박도윤", "expect": "record", "pause": 0.52, "raw": "하나야 1번 보일러 과일 이렇게 해 줘", "hot": "하나야 1번 보일러 과열 기록해 줘"},
    {"id": "S07", "voice": "김하늘", "expect": "record", "pause": 0.20, "raw": "하나야 3번 펌프 점검 완료 기록해 줘"},
    {"id": "S08", "voice": "박도윤", "expect": "ignore", "pause": 0.10, "raw": "3번 펌프 상태 좀 봐"},
    {"id": "S09", "voice": "김하늘", "expect": "ignore", "pause": 0.14, "raw": "오늘 점심은 뭐 먹지"},
    {"id": "S10", "voice": "외부인2", "expect": "refuse", "pause": 0.13, "raw": "하나야 3번 펌프 상태 알려 줘"},
    {"id": "S11", "voice": "외부인1", "expect": "refuse", "pause": 0.16, "raw": "하나야 1번 보일러 상태 알려 줘"},
    {"id": "S12", "voice": "외부인3", "expect": "refuse", "pause": 0.11, "raw": "하나야 5번 압축기 정지 기록해 줘"},
    {"id": "S13", "voice": "김하늘", "expect": "reask", "pause": 0.17, "raw": "하나야 4번 냉각기 상태 알려 줘"},
    {"id": "S14", "voice": "김하늘", "expect": "status", "pause": 0.19, "raw": "하나야 3번 펌프 상태 알려 줘", "int8": "하나야 3번 퍼프 상태 알려 줘"},
    {"id": "S15", "voice": "박도윤", "expect": "last", "pause": 0.14, "raw": "하나야 마지막 기록 읽어 줘"},
]
REPLIES = {"status": "3번 펌프는 정상입니다. 계속 가동해도 됩니다.", "record": "기록했습니다. 5번 압축기 정지입니다.", "refuse": "등록된 작업자만 쓸 수 있습니다.",
           "reask": "그 설비는 목록에 없습니다. 다시 말씀해 주세요.", "last": "마지막 기록은 5번 압축기 정지입니다. 기록한 사람은 김하늘입니다."}


def find(words, vocab, fuzzy):
    """낱말 앞부분과 사전 낱말의 자모 거리가 (음절 수 x fuzzy) 이하인 가장 가까운 사전 낱말."""
    best = None
    for w in vocab:
        for t in words:
            dist = jamo_dist(w, t[:len(w)])
            if dist <= len(w) * fuzzy and (best is None or dist < best[0]):
                best = (dist, w)
    return best[1] if best else None


def handle(d, s, idx, enrolled, log):
    """한 시나리오를 처리해 (결과, 기록자 이름)을 돌려준다. 결과: ignore · refuse · reask · status · record · last"""
    heard = s["raw"]
    if d["method"] == "modified_beam_search" and d["hotwords"]:
        heard = s.get("hot", heard)
    elif d["asr"] == "int8":
        heard = s.get("int8", heard)
    if d["endpoint"] <= s["pause"]:                       # 말 중간의 쉼에서 끝났다고 보고 잘라 버린다
        heard = heard.split()[0]
    if not heard_wake(heard, 3 * d["fuzzy"]):
        return "ignore", None
    name = who(embed(d["sv"], s["voice"], 200 + idx), enrolled, d["sv_th"])
    if name is None:
        return "refuse", None
    words = heard.split()[1:]
    intent, equip = find(words, INTENTS, d["fuzzy"]), find(words, EQUIP, d["fuzzy"])
    if intent == "마지막":
        return ("last", name) if log else ("reask", name)
    if intent is None or equip is None:
        return "reask", name
    if intent == "기록":
        log.append((name, equip))
        return "record", name
    return "status", name


def run_scenarios(d):
    enrolled, log, rows = enroll(d["sv"]), [], []
    for i, s in enumerate(SCENES):
        result, name = handle(d, s, i, enrolled, log)
        ok = result == s["expect"] and (s["expect"] != "record" or name == s["voice"])
        rows.append({"id": s["id"], "voice": s["voice"], "expect": s["expect"], "result": result, "name": name, "ok": ok, "cut": d["endpoint"] <= s["pause"]})
    passed = sum(r["ok"] for r in rows)
    leaks = sum(1 for r in rows if r["voice"].startswith("외부인") and r["result"] in ("status", "record", "last"))
    return {"rows": rows, "passed": passed, "score": round_half_up(passed / len(rows) * 100, 1), "leaks": leaks}


def measure(d, res):
    """예산 네 칸을 잰다. 지연은 소리로 답한 시나리오들의 중앙값(p50)."""
    spoken = [REPLIES[r["result"]] for r in res["rows"] if r["result"] != "ignore"]
    lat = [round_half_up(sum(latency_parts(d, t).values()), 2) for t in spoken]
    return {"모델(MB)": model_mb(d), "RAM(MB)": ram_mb(d), "지연(초)": percentile(lat, 50), "명료도(CER%)": clarity(d["tts_steps"]), "부품": parts_mb(d), "lat": lat}


# 1) 원리: 가중치 하나하나를 8비트 정수로 다시 적는다 (scale = 가장 큰 값 / 127)
weights = [w * 0.8 for w in rand_list(5, 64)]
scale = max(abs(w) for w in weights) / 127
q = [round_half_up(w / scale, 0) for w in weights]         # -127 ~ 127 정수
back = [x * scale for x in q]
err = max(abs(a - b) for a, b in zip(weights, back))
print(f"가중치 {len(weights)}개: scale {scale:.5f} - 정수 범위 {int(min(q))} ~ {int(max(q))} - 가장 큰 복원 오차 {err:.5f} (scale/2 = {scale / 2:.5f})")
print(f"크기: float32 {4 * len(weights)} 바이트 -> int8 {len(weights)} 바이트 ({4 * len(weights) / len(weights):.0f}배)")

# 2) 파일 크기는 4배가 아니라 2.4배: 모든 층을 바꾸지는 않는다
fp32_mb, int8_mb = ASR_MB["fp32"], ASR_MB["int8"]
frac = (fp32_mb - int8_mb) / (fp32_mb * 0.75)              # 8비트로 바꾼 층의 비중 (바꾼 층은 1/4 크기)
print(f"받아쓰기 모델 {fp32_mb} MB -> {int8_mb} MB ({fp32_mb / int8_mb:.1f}배) - 8비트로 바꾼 층의 비중 {frac:.0%}")

# 3) 설계에서 asr만 바꾸고(나머지는 기준 설계 그대로) 다시 잰다
QA = {}
for prec in ["fp32", "int8"]:
    d = {**BASELINE, "asr": prec}
    res = run_scenarios(d)
    m = measure(d, res)
    QA[prec] = {"받아쓰기 모델(MB)": m["부품"]["받아쓰기"], "합계(MB)": m["모델(MB)"], "RAM(MB)": m["RAM(MB)"], "마무리(초)": round_half_up(asr_tail(d), 3), "통과": res["passed"]}
    print(f"asr={prec}:", QA[prec])
print(f"int8로 바꾸면: 받아쓰기 모델 {QA['fp32']['받아쓰기 모델(MB)'] / QA['int8']['받아쓰기 모델(MB)']:.1f}배 작아짐 - RAM {QA['fp32']['RAM(MB)'] - QA['int8']['RAM(MB)']:.0f} MB 줄어듦 - "
      f"기능 통과 {QA['fp32']['통과']} -> {QA['int8']['통과']}")
lost = [r["id"] for a, b in zip(run_scenarios({**BASELINE, "asr": "fp32"})["rows"], run_scenarios({**BASELINE, "asr": "int8"})["rows"]) for r in [a] if a["ok"] and not b["ok"]]
print("int8로 바꿔서 틀리게 된 시나리오:", lost or "없음", "(바꾼 뒤에는 반드시 기능 점수를 다시 잰다)")

check(err <= scale / 2 + 1e-12 and max(abs(x) for x in q) == 127 and len(q) == len(weights), "복원 오차는 scale의 절반 이하이고 가장 큰 가중치는 127이 돼야 해요.")
check(QA["int8"]["받아쓰기 모델(MB)"] < 0.5 * QA["fp32"]["받아쓰기 모델(MB)"], "int8 받아쓰기 모델은 fp32의 절반보다 작아야 해요.")
check(QA["int8"]["RAM(MB)"] < QA["fp32"]["RAM(MB)"] - 80, "int8로 바꾸면 RAM이 80 MB 넘게 줄어야 해요.")
check(QA["int8"]["마무리(초)"] < QA["fp32"]["마무리(초)"] and abs(QA["int8"]["통과"] - QA["fp32"]["통과"]) <= 2 and 0.5 < frac < 1,
      "받아쓰기 마무리는 빨라지고 기능 통과 수는 비슷해야 해요(양자화는 늘 공짜는 아니라서 다시 잰다).")

quant.typescript:
// D50 · 같은 모델을 더 작게 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d50_quant.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 화자 검증 · 말하기 모델은 쓰지 않고 표와 규칙으로 흉내)
//   int8 양자화: 숫자를 32비트에서 8비트로 다시 적어 크기가 줄어드는 원리 + 설계의 asr만 바꿔 크기 - RAM - 기능을 다시 재기
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

const sum = (xs: number[]): number => xs.reduce((a, b) => a + b, 0);
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b);
const keyMax = (o: Record<string, number>): string => Object.keys(o).reduce((a, b) => (o[b] > o[a] ? b : a));

// ---- 제약 카드: 예산 네 칸 (숫자는 이 코드를 위해 지어낸 값이라 수업 카드와 같지 않다)
const BUDGET_KEYS = ["모델(MB)", "RAM(MB)", "지연(초)", "명료도(CER%)"];
type Measured = Record<string, number>;
type Card = Measured & { name: string };
const CARDS: Record<string, Card> = {
  A: { name: "작은 저장 공간", "모델(MB)": 320, "RAM(MB)": 700, "지연(초)": 2.5, "명료도(CER%)": 20 },
  B: { name: "작은 메모리", "모델(MB)": 500, "RAM(MB)": 560, "지연(초)": 2.5, "명료도(CER%)": 20 },
  C: { name: "빠른 응답", "모델(MB)": 500, "RAM(MB)": 700, "지연(초)": 1.5, "명료도(CER%)": 20 },
  D: { name: "모두 빠듯", "모델(MB)": 330, "RAM(MB)": 600, "지연(초)": 1.7, "명료도(CER%)": 20 },
};

function violations(measured: Measured, card: Measured): string[] {
  // 예산을 넘은 칸의 이름. 같으면 넘지 않은 것이다
  return BUDGET_KEYS.filter((k) => measured[k] > card[k]);
}

function percentile(xs: number[], q: number): number {
  // 가까운 순위 방식 백분위수: 작은 것부터 줄 세워 k번째 값 (k = ceil(q/100 x 개수), 최소 1)
  const s = [...xs].sort((a, b) => a - b);
  const k = Math.max(1, Math.ceil((q * s.length) / 100));
  return s[k - 1];
}

function finalScore(func: number, nViol: number): number {
  // 예산을 하나라도 넘으면(하나든 셋이든) 기능 점수의 절반
  return roundHalfUp(nViol === 0 ? func : func * 0.5, 1);
}

// ---- 설계 열 가지와 예산을 재는 가상 저울 (실제 모델 대신 크기 · 시간 표를 쓴다)
interface Design {
  asr: string; threads: number; method: string; hotwords: string[]; endpoint: number;
  fuzzy: number; sv: string; sv_th: number; tts_steps: number; first_sentence: boolean;
}
const BASELINE: Design = { asr: "fp32", threads: 2, method: "greedy_search", hotwords: [], endpoint: 1.2, fuzzy: 0, sv: "campp", sv_th: 0.5, tts_steps: 8, first_sentence: false };
const ASR_MB: Record<string, number> = { fp32: 314.0, int8: 132.0 }; // 받아쓰기 모델 파일 크기
const SV_MB: Record<string, number> = { campp: 28.0, titanet: 40.0 }; // 화자 검증 모델 파일 크기
const TTS_MB = 144.0; // 말하기 모델
const ETC_MB = 1.8; // 나머지(어휘 · 설정)
const ASR_TAIL: Record<string, number> = { fp32: 0.16, int8: 0.11 }; // 받아쓰기 마무리 시간(초, 기준 기계 · 스레드 1개)
const SV_SEC: Record<string, number> = { campp: 0.05, titanet: 0.09 }; // 화자 검증 시간(초)
const CER_BY_STEPS = [92.0, 62.0, 41.0, 24.0, 14.0, 9.0, 7.5, 6.6, 6.4, 6.3, 6.2, 6.2]; // 말하기 단계 1~12의 명료도 CER(%)

function partsMb(d: Design): Record<string, number> {
  return { "받아쓰기": ASR_MB[d.asr], "말하기": TTS_MB, "화자 검증": SV_MB[d.sv], "기타": ETC_MB };
}

function modelMb(d: Design): number {
  return roundHalfUp(sum(Object.values(partsMb(d))), 1);
}

function ramMb(d: Design): number {
  const beam = d.method === "modified_beam_search" ? 25.0 : 0.0;
  return roundHalfUp(0.9 * modelMb(d) + 150 + 20 * d.threads + beam, 1);
}

function asrTail(d: Design): number {
  const beam = d.method === "modified_beam_search" ? 0.03 : 0.0;
  return ASR_TAIL[d.asr] / (1 + 0.3 * (d.threads - 1)) + beam;
}

function ttsTime(steps: number, chars: number): number {
  // 말하기 모델이 소리를 만드는 시간: 기본 시간 + 단계 x (글자 수에 비례)
  return 0.1 + steps * (0.02 + 0.0018 * chars);
}

function firstChunk(reply: string): string {
  // 답의 첫 문장만: 문장 끝 부호(. ? !) 뒤의 공백에서 나눈다
  return reply.trim().split(/(?<=[.?!])\s+/)[0];
}

function clarity(steps: number): number {
  return CER_BY_STEPS[steps - 1];
}

function latencyParts(d: Design, reply: string): Record<string, number> {
  // 말이 끝난 뒤 첫 소리까지의 네 단계(초)
  const text = d.first_sentence ? firstChunk(reply) : reply;
  return { "끝점 기다리기": d.endpoint, "받아쓰기 마무리": asrTail(d), "화자 검증": SV_SEC[d.sv], "첫 소리 만들기": ttsTime(d.tts_steps, text.length) };
}

// ---- 한글을 자모로 풀어 재는 편집 거리 (깨움말 · 용어 맞추기)
const CHO = Array.from("ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ");
const JUNG = Array.from("ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ");
const JONG = ["", "ㄱ", "ㄲ", "ㄳ", "ㄴ", "ㄵ", "ㄶ", "ㄷ", "ㄹ", "ㄺ", "ㄻ", "ㄼ", "ㄽ", "ㄾ", "ㄿ", "ㅀ", "ㅁ", "ㅂ", "ㅄ", "ㅅ", "ㅆ", "ㅇ", "ㅈ", "ㅊ", "ㅋ", "ㅌ", "ㅍ", "ㅎ"];

function jamo(text: string): string[] {
  const out: string[] = [];
  for (const ch of text) {
    const o = ch.codePointAt(0)! - 0xac00;
    if (o >= 0 && o < 11172) {
      out.push(CHO[Math.floor(o / 588)], JUNG[Math.floor((o % 588) / 28)]);
      if (o % 28) out.push(JONG[o % 28]);
    } else {
      out.push(ch);
    }
  }
  return out;
}

function jamoDist(a: string, b: string): number {
  const x = jamo(a);
  const y = jamo(b);
  const row = Array.from({ length: y.length + 1 }, (_, j) => j);
  for (let i = 1; i <= x.length; i++) {
    let prev = row[0];
    row[0] = i;
    for (let j = 1; j <= y.length; j++) {
      const cur = row[j];
      row[j] = Math.min(row[j] + 1, row[j - 1] + 1, prev + (x[i - 1] !== y[j - 1] ? 1 : 0));
      prev = cur;
    }
  }
  return row[y.length];
}

function heardWake(text: string, allowed: number): boolean {
  // 받아쓴 글의 앞 세 글자가 깨움말 '하나야'와 자모 거리 allowed 이내인가
  const t = text.replace(/[^0-9A-Za-z가-힣]/g, "");
  return jamoDist("하나야", t.slice(0, 3)) <= allowed;
}

// ---- 목소리: 코사인 유사도와 화자 검증 (임베딩은 모델 대신 난수 벡터에 소음을 섞어 흉내)
function cosine(a: number[], b: number[]): number {
  const dot = sum(a.map((x, i) => x * b[i]));
  return dot / (Math.sqrt(sum(a.map((x) => x * x))) * Math.sqrt(sum(b.map((y) => y * y))));
}

function who(emb: number[], enrolled: Record<string, number[]>, th: number): string | null {
  // 등록된 사람 가운데 가장 비슷한 이름. 유사도가 문턱값 미만이면 null
  let best: string | null = null;
  let score = -1.0;
  for (const [name, vec] of Object.entries(enrolled)) {
    const s = cosine(emb, vec);
    if (s > score) {
      best = name;
      score = s;
    }
  }
  return score >= th ? best : null;
}

function randList(seed: number, n: number): number[] {
  // 같은 seed면 늘 같은 -1 ~ 1 난수 n개 (Park-Miller, Python · TS가 똑같이 나온다)
  const out: number[] = [];
  let s = seed;
  for (let i = 0; i < n; i++) {
    s = (s * 48271) % 2147483647;
    out.push((s / 2147483647) * 2 - 1);
  }
  return out;
}

const DIM = 12;
const H = randList(11, DIM);
const D = randList(23, DIM);
const R31 = randList(31, DIM);
const VOICES: Record<string, number[]> = {
  "김하늘": H, "박도윤": D, "외부인1": H.map((h, i) => 0.25 * h + 0.75 * R31[i]),
  "외부인2": randList(47, DIM), "외부인3": randList(59, DIM),
};
const COMMON = randList(7, DIM); // 모든 목소리에 깔리는 공통 성분: campp는 이것이 커서 남남도 어느 정도 닮아 보인다
const SV_BIAS: Record<string, number> = { campp: 0.8, titanet: 0.0 };
const SV_NOISE: Record<string, number> = { campp: 0.6, titanet: 0.4 }; // titanet이 더 또렷하게 가른다 (대신 12 MB 더 큼)

function embed(model: string, voice: string, seed: number): number[] {
  const noise = randList(seed, DIM);
  return VOICES[voice].map((v, i) => v + SV_BIAS[model] * COMMON[i] + SV_NOISE[model] * noise[i]);
}

function enroll(model: string): Record<string, number[]> {
  // 작업자마다 등록 음성 2개의 평균 벡터
  const out: Record<string, number[]> = {};
  ["김하늘", "박도윤"].forEach((w, i) => {
    const a = embed(model, w, 1 + i * 2);
    const b = embed(model, w, 2 + i * 2);
    out[w] = a.map((x, k) => (x + b[k]) / 2);
  });
  return out;
}

// ---- 시나리오 15개: 말한 사람 · 기대하는 일 · 말 안의 가장 긴 쉼(초) · 받아쓴 글 (int8 · 핫워드 빔 탐색일 때 달라지는 것만 따로)
const EQUIP = ["펌프", "컨베이어", "보일러", "압축기"];
const INTENTS = ["마지막", "상태", "기록"];
interface Scene { id: string; voice: string; expect: string; pause: number; raw: string; int8?: string; hot?: string }
const SCENES: Scene[] = [
  { id: "S01", voice: "김하늘", expect: "status", pause: 0.12, raw: "하나야 3번 펌프 상태 알려 줘" },
  { id: "S02", voice: "박도윤", expect: "status", pause: 0.30, raw: "하나야 1번 보일러 상태 알려 줘" },
  { id: "S03", voice: "김하늘", expect: "status", pause: 0.18, raw: "하나야 2번 컴레이어 상태 알려 줘", hot: "하나야 2번 컨베이어 상태 알려 줘" },
  { id: "S04", voice: "박도윤", expect: "status", pause: 0.56, raw: "하나야 5번 압축기 상태 알려 줘" },
  { id: "S05", voice: "김하늘", expect: "record", pause: 0.15, raw: "하나에 5번 압축기 정지 기록해 줘" },
  { id: "S06", voice: "박도윤", expect: "record", pause: 0.52, raw: "하나야 1번 보일러 과일 이렇게 해 줘", hot: "하나야 1번 보일러 과열 기록해 줘" },
  { id: "S07", voice: "김하늘", expect: "record", pause: 0.20, raw: "하나야 3번 펌프 점검 완료 기록해 줘" },
  { id: "S08", voice: "박도윤", expect: "ignore", pause: 0.10, raw: "3번 펌프 상태 좀 봐" },
  { id: "S09", voice: "김하늘", expect: "ignore", pause: 0.14, raw: "오늘 점심은 뭐 먹지" },
  { id: "S10", voice: "외부인2", expect: "refuse", pause: 0.13, raw: "하나야 3번 펌프 상태 알려 줘" },
  { id: "S11", voice: "외부인1", expect: "refuse", pause: 0.16, raw: "하나야 1번 보일러 상태 알려 줘" },
  { id: "S12", voice: "외부인3", expect: "refuse", pause: 0.11, raw: "하나야 5번 압축기 정지 기록해 줘" },
  { id: "S13", voice: "김하늘", expect: "reask", pause: 0.17, raw: "하나야 4번 냉각기 상태 알려 줘" },
  { id: "S14", voice: "김하늘", expect: "status", pause: 0.19, raw: "하나야 3번 펌프 상태 알려 줘", int8: "하나야 3번 퍼프 상태 알려 줘" },
  { id: "S15", voice: "박도윤", expect: "last", pause: 0.14, raw: "하나야 마지막 기록 읽어 줘" },
];
const REPLIES: Record<string, string> = {
  status: "3번 펌프는 정상입니다. 계속 가동해도 됩니다.", record: "기록했습니다. 5번 압축기 정지입니다.", refuse: "등록된 작업자만 쓸 수 있습니다.",
  reask: "그 설비는 목록에 없습니다. 다시 말씀해 주세요.", last: "마지막 기록은 5번 압축기 정지입니다. 기록한 사람은 김하늘입니다.",
};

function find(words: string[], vocab: string[], fuzzy: number): string | null {
  // 낱말 앞부분과 사전 낱말의 자모 거리가 (음절 수 x fuzzy) 이하인 가장 가까운 사전 낱말
  let best: [number, string] | null = null;
  for (const w of vocab) {
    for (const t of words) {
      const dist = jamoDist(w, t.slice(0, w.length));
      if (dist <= w.length * fuzzy && (best === null || dist < best[0])) best = [dist, w];
    }
  }
  return best ? best[1] : null;
}

const words = (s: string): string[] => s.split(/\s+/).filter((w) => w.length > 0);

function handle(d: Design, s: Scene, idx: number, enrolled: Record<string, number[]>, log: [string, string][]): [string, string | null] {
  // 한 시나리오를 처리해 [결과, 기록자 이름]을 돌려준다. 결과: ignore · refuse · reask · status · record · last
  let heard = s.raw;
  if (d.method === "modified_beam_search" && d.hotwords.length > 0) heard = s.hot ?? heard;
  else if (d.asr === "int8") heard = s.int8 ?? heard;
  if (d.endpoint <= s.pause) heard = words(heard)[0]; // 말 중간의 쉼에서 끝났다고 보고 잘라 버린다
  if (!heardWake(heard, 3 * d.fuzzy)) return ["ignore", null];
  const name = who(embed(d.sv, s.voice, 200 + idx), enrolled, d.sv_th);
  if (name === null) return ["refuse", null];
  const rest = words(heard).slice(1);
  const intent = find(rest, INTENTS, d.fuzzy);
  const equip = find(rest, EQUIP, d.fuzzy);
  if (intent === "마지막") return log.length > 0 ? ["last", name] : ["reask", name];
  if (intent === null || equip === null) return ["reask", name];
  if (intent === "기록") {
    log.push([name, equip]);
    return ["record", name];
  }
  return ["status", name];
}

interface Row { id: string; voice: string; expect: string; result: string; name: string | null; ok: boolean; cut: boolean }
interface Result { rows: Row[]; passed: number; score: number; leaks: number }

function runScenarios(d: Design): Result {
  const enrolled = enroll(d.sv);
  const log: [string, string][] = [];
  const rows: Row[] = SCENES.map((s, i) => {
    const [result, name] = handle(d, s, i, enrolled, log);
    const ok = result === s.expect && (s.expect !== "record" || name === s.voice);
    return { id: s.id, voice: s.voice, expect: s.expect, result, name, ok, cut: d.endpoint <= s.pause };
  });
  const passed = rows.filter((r) => r.ok).length;
  const leaks = rows.filter((r) => r.voice.startsWith("외부인") && ["status", "record", "last"].includes(r.result)).length;
  return { rows, passed, score: roundHalfUp((passed / rows.length) * 100, 1), leaks };
}

function measure(d: Design, res: Result): { m: Measured; parts: Record<string, number>; lat: number[] } {
  // 예산 네 칸을 잰다. 지연은 소리로 답한 시나리오들의 중앙값(p50)
  const spoken = res.rows.filter((r) => r.result !== "ignore").map((r) => REPLIES[r.result]);
  const lat = spoken.map((t) => roundHalfUp(sum(Object.values(latencyParts(d, t))), 2));
  return { m: { "모델(MB)": modelMb(d), "RAM(MB)": ramMb(d), "지연(초)": percentile(lat, 50), "명료도(CER%)": clarity(d.tts_steps) }, parts: partsMb(d), lat };
}

// 1) 원리: 가중치 하나하나를 8비트 정수로 다시 적는다 (scale = 가장 큰 값 / 127)
const weights = randList(5, 64).map((w) => w * 0.8);
const scale = Math.max(...weights.map(Math.abs)) / 127;
const q = weights.map((w) => roundHalfUp(w / scale, 0)); // -127 ~ 127 정수
const restored = q.map((x) => x * scale);
const err = Math.max(...weights.map((w, i) => Math.abs(w - restored[i])));
console.log(`가중치 ${weights.length}개: scale ${scale.toFixed(5)} - 정수 범위 ${Math.min(...q)} ~ ${Math.max(...q)} - 가장 큰 복원 오차 ${err.toFixed(5)} (scale/2 = ${(scale / 2).toFixed(5)})`);
console.log(`크기: float32 ${4 * weights.length} 바이트 -> int8 ${weights.length} 바이트 (${(4 * weights.length) / weights.length}배)`);

// 2) 파일 크기는 4배가 아니라 2.4배: 모든 층을 바꾸지는 않는다
const fp32Mb = ASR_MB.fp32;
const int8Mb = ASR_MB.int8;
const frac = (fp32Mb - int8Mb) / (fp32Mb * 0.75); // 8비트로 바꾼 층의 비중 (바꾼 층은 1/4 크기)
console.log(`받아쓰기 모델 ${fp32Mb} MB -> ${int8Mb} MB (${(fp32Mb / int8Mb).toFixed(1)}배) - 8비트로 바꾼 층의 비중 ${Math.round(frac * 100)}%`);

// 3) 설계에서 asr만 바꾸고(나머지는 기준 설계 그대로) 다시 잰다
const QA: Record<string, { 받아쓰기: number; 합계: number; ram: number; 마무리: number; 통과: number }> = {};
for (const prec of ["fp32", "int8"]) {
  const d: Design = { ...BASELINE, asr: prec };
  const res = runScenarios(d);
  const { m, parts } = measure(d, res);
  QA[prec] = { 받아쓰기: parts["받아쓰기"], 합계: m["모델(MB)"], ram: m["RAM(MB)"], 마무리: roundHalfUp(asrTail(d), 3), 통과: res.passed };
  console.log(`asr=${prec}:`, JSON.stringify(QA[prec]));
}
console.log(`int8로 바꾸면: 받아쓰기 모델 ${(QA.fp32.받아쓰기 / QA.int8.받아쓰기).toFixed(1)}배 작아짐 - RAM ${(QA.fp32.ram - QA.int8.ram).toFixed(0)} MB 줄어듦 - 기능 통과 ${QA.fp32.통과} -> ${QA.int8.통과}`);
const rowsA = runScenarios({ ...BASELINE, asr: "fp32" }).rows;
const rowsB = runScenarios({ ...BASELINE, asr: "int8" }).rows;
const lost = rowsA.filter((a, i) => a.ok && !rowsB[i].ok).map((a) => a.id);
console.log("int8로 바꿔서 틀리게 된 시나리오:", lost.length ? lost.join(" ") : "없음", "(바꾼 뒤에는 반드시 기능 점수를 다시 잰다)");

check(err <= scale / 2 + 1e-12 && Math.max(...q.map(Math.abs)) === 127 && q.length === weights.length, "복원 오차는 scale의 절반 이하이고 가장 큰 가중치는 127이 돼야 해요.");
check(QA.int8.받아쓰기 < 0.5 * QA.fp32.받아쓰기, "int8 받아쓰기 모델은 fp32의 절반보다 작아야 해요.");
check(QA.int8.ram < QA.fp32.ram - 80, "int8로 바꾸면 RAM이 80 MB 넘게 줄어야 해요.");
check(QA.int8.마무리 < QA.fp32.마무리 && Math.abs(QA.int8.통과 - QA.fp32.통과) <= 2 && frac > 0.5 && frac < 1, "받아쓰기 마무리는 빨라지고 기능 통과 수는 비슷해야 해요(양자화는 늘 공짜는 아니라서 다시 잰다).");

endpoint.python:
# D50 · 끝점: 얼마나 기다릴까 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d50_endpoint.py   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 화자 검증 · 말하기 모델은 쓰지 않고 표와 규칙으로 흉내)
#   끝점: 조용한 구간을 몇 초 기다려야 말이 끝난 걸까. 소리 크기 조각에서 직접 찾아 보고, 값을 바꿔 지연과 잘림을 맞바꾸기
import math, re


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def round_half_up(x, nd=1):
    """반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)"""
    f = 10 ** nd
    return math.copysign(math.floor(abs(x) * f + 0.5) / f, x)


# ---- 제약 카드: 예산 네 칸 (숫자는 이 코드를 위해 지어낸 값이라 수업 카드와 같지 않다)
BUDGET_KEYS = ["모델(MB)", "RAM(MB)", "지연(초)", "명료도(CER%)"]
CARDS = {
    "A": {"name": "작은 저장 공간", "모델(MB)": 320, "RAM(MB)": 700, "지연(초)": 2.5, "명료도(CER%)": 20},
    "B": {"name": "작은 메모리", "모델(MB)": 500, "RAM(MB)": 560, "지연(초)": 2.5, "명료도(CER%)": 20},
    "C": {"name": "빠른 응답", "모델(MB)": 500, "RAM(MB)": 700, "지연(초)": 1.5, "명료도(CER%)": 20},
    "D": {"name": "모두 빠듯", "모델(MB)": 330, "RAM(MB)": 600, "지연(초)": 1.7, "명료도(CER%)": 20},
}


def violations(measured, card):
    """예산을 넘은 칸의 이름. 같으면 넘지 않은 것이다."""
    return [k for k in BUDGET_KEYS if measured[k] > card[k]]


def percentile(xs, q):
    """가까운 순위 방식 백분위수: 작은 것부터 줄 세워 k번째 값 (k = ceil(q/100 x 개수), 최소 1)."""
    s = sorted(xs)
    k = max(1, math.ceil(q * len(s) / 100))
    return s[k - 1]


def final_score(func, n_viol):
    """예산을 하나라도 넘으면(하나든 셋이든) 기능 점수의 절반."""
    return round_half_up(func if n_viol == 0 else func * 0.5, 1)


# ---- 설계 열 가지와 예산을 재는 가상 저울 (실제 모델 대신 크기 · 시간 표를 쓴다)
BASELINE = {"asr": "fp32", "threads": 2, "method": "greedy_search", "hotwords": [], "endpoint": 1.2, "fuzzy": 0,
            "sv": "campp", "sv_th": 0.5, "tts_steps": 8, "first_sentence": False}
ASR_MB = {"fp32": 314.0, "int8": 132.0}                   # 받아쓰기 모델 파일 크기
SV_MB = {"campp": 28.0, "titanet": 40.0}                  # 화자 검증 모델 파일 크기
TTS_MB, ETC_MB = 144.0, 1.8                               # 말하기 모델 · 나머지(어휘 · 설정)
ASR_TAIL = {"fp32": 0.16, "int8": 0.11}                   # 받아쓰기 마무리 시간(초, 기준 기계 · 스레드 1개)
SV_SEC = {"campp": 0.05, "titanet": 0.09}                 # 화자 검증 시간(초)
CER_BY_STEPS = [92.0, 62.0, 41.0, 24.0, 14.0, 9.0, 7.5, 6.6, 6.4, 6.3, 6.2, 6.2]   # 말하기 단계 1~12의 명료도 CER(%)


def parts_mb(d):
    return {"받아쓰기": ASR_MB[d["asr"]], "말하기": TTS_MB, "화자 검증": SV_MB[d["sv"]], "기타": ETC_MB}


def model_mb(d):
    return round_half_up(sum(parts_mb(d).values()), 1)


def ram_mb(d):
    beam = 25.0 if d["method"] == "modified_beam_search" else 0.0
    return round_half_up(0.9 * model_mb(d) + 150 + 20 * d["threads"] + beam, 1)


def asr_tail(d):
    beam = 0.03 if d["method"] == "modified_beam_search" else 0.0
    return ASR_TAIL[d["asr"]] / (1 + 0.3 * (d["threads"] - 1)) + beam


def tts_time(steps, chars):
    """말하기 모델이 소리를 만드는 시간: 기본 시간 + 단계 x (글자 수에 비례)."""
    return 0.10 + steps * (0.02 + 0.0018 * chars)


def first_chunk(reply):
    """답의 첫 문장만: 문장 끝 부호(. ? !) 뒤의 공백에서 나눈다."""
    return re.split(r"(?<=[.?!])\s+", reply.strip())[0]


def clarity(steps):
    return CER_BY_STEPS[steps - 1]


def latency_parts(d, reply):
    """말이 끝난 뒤 첫 소리까지의 네 단계(초)."""
    text = first_chunk(reply) if d["first_sentence"] else reply
    return {"끝점 기다리기": d["endpoint"], "받아쓰기 마무리": asr_tail(d), "화자 검증": SV_SEC[d["sv"]], "첫 소리 만들기": tts_time(d["tts_steps"], len(text))}


# ---- 한글을 자모로 풀어 재는 편집 거리 (깨움말 · 용어 맞추기)
CHO = "ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ"
JUNG = "ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ"
JONG = ["", "ㄱ", "ㄲ", "ㄳ", "ㄴ", "ㄵ", "ㄶ", "ㄷ", "ㄹ", "ㄺ", "ㄻ", "ㄼ", "ㄽ", "ㄾ", "ㄿ", "ㅀ", "ㅁ", "ㅂ", "ㅄ", "ㅅ", "ㅆ", "ㅇ", "ㅈ", "ㅊ", "ㅋ", "ㅌ", "ㅍ", "ㅎ"]


def jamo(text):
    out = []
    for ch in text:
        o = ord(ch) - 0xAC00
        if 0 <= o < 11172:
            out += [CHO[o // 588], JUNG[(o % 588) // 28]] + ([JONG[o % 28]] if o % 28 else [])
        else:
            out.append(ch)
    return out


def jamo_dist(a, b):
    x, y = jamo(a), jamo(b)
    row = list(range(len(y) + 1))
    for i in range(1, len(x) + 1):
        prev, row[0] = row[0], i
        for j in range(1, len(y) + 1):
            cur = row[j]
            row[j] = min(row[j] + 1, row[j - 1] + 1, prev + (x[i - 1] != y[j - 1]))
            prev = cur
    return row[len(y)]


def heard_wake(text, allowed):
    """받아쓴 글의 앞 세 글자가 깨움말 '하나야'와 자모 거리 allowed 이내인가."""
    t = re.sub(r"[^0-9A-Za-z가-힣]", "", text)
    return jamo_dist("하나야", t[:3]) <= allowed


# ---- 목소리: 코사인 유사도와 화자 검증 (임베딩은 모델 대신 난수 벡터에 소음을 섞어 흉내)
def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    return dot / (math.sqrt(sum(x * x for x in a)) * math.sqrt(sum(y * y for y in b)))


def who(emb, enrolled, th):
    """등록된 사람 가운데 가장 비슷한 이름. 유사도가 문턱값 미만이면 None."""
    best, score = None, -1.0
    for name, vec in enrolled.items():
        s = cosine(emb, vec)
        if s > score:
            best, score = name, s
    return best if score >= th else None


def rand_list(seed, n):
    """같은 seed면 늘 같은 -1 ~ 1 난수 n개 (Park-Miller, Python · TS가 똑같이 나온다)."""
    out, s = [], seed
    for _ in range(n):
        s = s * 48271 % 2147483647
        out.append(s / 2147483647 * 2 - 1)
    return out


DIM = 12
_H, _D = rand_list(11, DIM), rand_list(23, DIM)
VOICES = {"김하늘": _H, "박도윤": _D, "외부인1": [0.25 * h + 0.75 * r for h, r in zip(_H, rand_list(31, DIM))],
          "외부인2": rand_list(47, DIM), "외부인3": rand_list(59, DIM)}
COMMON = rand_list(7, DIM)                                # 모든 목소리에 깔리는 공통 성분: campp는 이것이 커서 남남도 어느 정도 닮아 보인다
SV_BIAS = {"campp": 0.8, "titanet": 0.0}
SV_NOISE = {"campp": 0.6, "titanet": 0.4}               # titanet이 더 또렷하게 가른다 (대신 12 MB 더 큼)


def embed(model, voice, seed):
    return [v + SV_BIAS[model] * c + SV_NOISE[model] * n for v, c, n in zip(VOICES[voice], COMMON, rand_list(seed, DIM))]


def enroll(model):
    """작업자마다 등록 음성 2개의 평균 벡터."""
    return {w: [(a + b) / 2 for a, b in zip(embed(model, w, 1 + i * 2), embed(model, w, 2 + i * 2))] for i, w in enumerate(["김하늘", "박도윤"])}


# ---- 시나리오 15개: 말한 사람 · 기대하는 일 · 말 안의 가장 긴 쉼(초) · 받아쓴 글 (int8 · 핫워드 빔 탐색일 때 달라지는 것만 따로)
EQUIP = ["펌프", "컨베이어", "보일러", "압축기"]
INTENTS = ["마지막", "상태", "기록"]
SCENES = [
    {"id": "S01", "voice": "김하늘", "expect": "status", "pause": 0.12, "raw": "하나야 3번 펌프 상태 알려 줘"},
    {"id": "S02", "voice": "박도윤", "expect": "status", "pause": 0.30, "raw": "하나야 1번 보일러 상태 알려 줘"},
    {"id": "S03", "voice": "김하늘", "expect": "status", "pause": 0.18, "raw": "하나야 2번 컴레이어 상태 알려 줘", "hot": "하나야 2번 컨베이어 상태 알려 줘"},
    {"id": "S04", "voice": "박도윤", "expect": "status", "pause": 0.56, "raw": "하나야 5번 압축기 상태 알려 줘"},
    {"id": "S05", "voice": "김하늘", "expect": "record", "pause": 0.15, "raw": "하나에 5번 압축기 정지 기록해 줘"},
    {"id": "S06", "voice": "박도윤", "expect": "record", "pause": 0.52, "raw": "하나야 1번 보일러 과일 이렇게 해 줘", "hot": "하나야 1번 보일러 과열 기록해 줘"},
    {"id": "S07", "voice": "김하늘", "expect": "record", "pause": 0.20, "raw": "하나야 3번 펌프 점검 완료 기록해 줘"},
    {"id": "S08", "voice": "박도윤", "expect": "ignore", "pause": 0.10, "raw": "3번 펌프 상태 좀 봐"},
    {"id": "S09", "voice": "김하늘", "expect": "ignore", "pause": 0.14, "raw": "오늘 점심은 뭐 먹지"},
    {"id": "S10", "voice": "외부인2", "expect": "refuse", "pause": 0.13, "raw": "하나야 3번 펌프 상태 알려 줘"},
    {"id": "S11", "voice": "외부인1", "expect": "refuse", "pause": 0.16, "raw": "하나야 1번 보일러 상태 알려 줘"},
    {"id": "S12", "voice": "외부인3", "expect": "refuse", "pause": 0.11, "raw": "하나야 5번 압축기 정지 기록해 줘"},
    {"id": "S13", "voice": "김하늘", "expect": "reask", "pause": 0.17, "raw": "하나야 4번 냉각기 상태 알려 줘"},
    {"id": "S14", "voice": "김하늘", "expect": "status", "pause": 0.19, "raw": "하나야 3번 펌프 상태 알려 줘", "int8": "하나야 3번 퍼프 상태 알려 줘"},
    {"id": "S15", "voice": "박도윤", "expect": "last", "pause": 0.14, "raw": "하나야 마지막 기록 읽어 줘"},
]
REPLIES = {"status": "3번 펌프는 정상입니다. 계속 가동해도 됩니다.", "record": "기록했습니다. 5번 압축기 정지입니다.", "refuse": "등록된 작업자만 쓸 수 있습니다.",
           "reask": "그 설비는 목록에 없습니다. 다시 말씀해 주세요.", "last": "마지막 기록은 5번 압축기 정지입니다. 기록한 사람은 김하늘입니다."}


def find(words, vocab, fuzzy):
    """낱말 앞부분과 사전 낱말의 자모 거리가 (음절 수 x fuzzy) 이하인 가장 가까운 사전 낱말."""
    best = None
    for w in vocab:
        for t in words:
            dist = jamo_dist(w, t[:len(w)])
            if dist <= len(w) * fuzzy and (best is None or dist < best[0]):
                best = (dist, w)
    return best[1] if best else None


def handle(d, s, idx, enrolled, log):
    """한 시나리오를 처리해 (결과, 기록자 이름)을 돌려준다. 결과: ignore · refuse · reask · status · record · last"""
    heard = s["raw"]
    if d["method"] == "modified_beam_search" and d["hotwords"]:
        heard = s.get("hot", heard)
    elif d["asr"] == "int8":
        heard = s.get("int8", heard)
    if d["endpoint"] <= s["pause"]:                       # 말 중간의 쉼에서 끝났다고 보고 잘라 버린다
        heard = heard.split()[0]
    if not heard_wake(heard, 3 * d["fuzzy"]):
        return "ignore", None
    name = who(embed(d["sv"], s["voice"], 200 + idx), enrolled, d["sv_th"])
    if name is None:
        return "refuse", None
    words = heard.split()[1:]
    intent, equip = find(words, INTENTS, d["fuzzy"]), find(words, EQUIP, d["fuzzy"])
    if intent == "마지막":
        return ("last", name) if log else ("reask", name)
    if intent is None or equip is None:
        return "reask", name
    if intent == "기록":
        log.append((name, equip))
        return "record", name
    return "status", name


def run_scenarios(d):
    enrolled, log, rows = enroll(d["sv"]), [], []
    for i, s in enumerate(SCENES):
        result, name = handle(d, s, i, enrolled, log)
        ok = result == s["expect"] and (s["expect"] != "record" or name == s["voice"])
        rows.append({"id": s["id"], "voice": s["voice"], "expect": s["expect"], "result": result, "name": name, "ok": ok, "cut": d["endpoint"] <= s["pause"]})
    passed = sum(r["ok"] for r in rows)
    leaks = sum(1 for r in rows if r["voice"].startswith("외부인") and r["result"] in ("status", "record", "last"))
    return {"rows": rows, "passed": passed, "score": round_half_up(passed / len(rows) * 100, 1), "leaks": leaks}


def measure(d, res):
    """예산 네 칸을 잰다. 지연은 소리로 답한 시나리오들의 중앙값(p50)."""
    spoken = [REPLIES[r["result"]] for r in res["rows"] if r["result"] != "ignore"]
    lat = [round_half_up(sum(latency_parts(d, t).values()), 2) for t in spoken]
    return {"모델(MB)": model_mb(d), "RAM(MB)": ram_mb(d), "지연(초)": percentile(lat, 50), "명료도(CER%)": clarity(d["tts_steps"]), "부품": parts_mb(d), "lat": lat}


FRAME = 0.02                                               # 20 ms 조각


def energy(parts):
    """(소리 있음/없음, 초) 토막들을 20 ms 조각마다 소리 크기 하나로: 소리 0.3, 쉼 0.0."""
    out = []
    for loud, sec in parts:
        out += [0.3 if loud else 0.0] * round(sec / FRAME)
    return out


def endpoint_cut(frames, wait):
    """조용한 조각이 wait초 이어지면 거기서 말이 끝났다고 보고 자른다. (자른 조각 수, 잘렸나)"""
    quiet = 0
    for i, e in enumerate(frames):
        quiet = quiet + 1 if e < 0.05 else 0
        if quiet * FRAME >= wait - 1e-9:
            return i + 1 - quiet, i + 1 < len(frames)       # 말 끝(조용해지기 직전)까지만 듣는다
    return len(frames), False


# S04: "하나야" 쉼 "5번 압축기 상태 알려 줘" - 중간의 쉼이 0.56초
s04 = energy([(True, 0.36), (False, 0.56), (True, 1.2)])
for wait in [0.3, 0.5, 0.6, 1.2]:
    n, cut = endpoint_cut(s04, wait)
    print(f"끝점 {wait}초: 비서가 들은 길이 {round_half_up(n * FRAME, 2)}초 / 전체 {round_half_up(len(s04) * FRAME, 2)}초 - " + ("말 중간에서 잘림" if cut else "끝까지 들음"))

EP = []
for ep in [0.3, 0.5, 0.6, 0.8, 1.2]:                       # 값 하나만 바꾼다: 나머지는 같은 설계
    d = {**BASELINE, "asr": "int8", "endpoint": ep}
    res = run_scenarios(d)
    m = measure(d, res)
    cut = [r["id"] for r in res["rows"] if r["cut"]]
    EP.append({"endpoint": ep, "p50": m["지연(초)"], "cut": cut, "passed": res["passed"]})
    print(f"endpoint {ep}: 지연 p50 {m['지연(초)']}초 - 잘린 발화 {len(cut)}개 {' '.join(cut)} - 기능 통과 {res['passed']}")
SAFE_EP = min(e["endpoint"] for e in EP if not e["cut"])
longest = max(s["pause"] for s in SCENES)
print(f"잘리지 않는 가장 짧은 값(시험한 것 가운데): {SAFE_EP}초 - 말 안의 가장 긴 쉼: {longest}초")

n04, cut04 = endpoint_cut(s04, 0.3)
check(cut04 and round_half_up(n04 * FRAME, 2) == 0.36, "S04를 0.3초에서 끊으면 '하나야'(0.36초)까지만 듣고 잘려야 해요.")
check(not endpoint_cut(s04, 0.6)[1] and not endpoint_cut(s04, 1.2)[1], "쉼(0.56초)보다 길게 기다리면 잘리지 않아야 해요.")
check(len(EP[0]["cut"]) >= 2 and EP[-1]["cut"] == [], "0.3초는 머뭇거리는 말이 2개 넘게 잘리고 1.2초는 하나도 안 잘려야 해요.")
check(EP[0]["p50"] < EP[-1]["p50"] - 0.6, "끝점을 줄이면 지연이 0.6초 넘게 줄어야 해요.")
check(longest < SAFE_EP <= 0.8 and 0.5 <= SAFE_EP, "잘리지 않는 가장 짧은 값은 말 안의 가장 긴 쉼보다 길고 0.5 ~ 0.8초 사이여야 해요.")
check(EP[0]["passed"] < EP[2]["passed"], "너무 줄인 끝점(0.3초)은 기능 통과가 줄어야 해요.")

endpoint.typescript:
// D50 · 끝점: 얼마나 기다릴까 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d50_endpoint.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 화자 검증 · 말하기 모델은 쓰지 않고 표와 규칙으로 흉내)
//   끝점: 조용한 구간을 몇 초 기다려야 말이 끝난 걸까. 소리 크기 조각에서 직접 찾아 보고, 값을 바꿔 지연과 잘림을 맞바꾸기
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

const sum = (xs: number[]): number => xs.reduce((a, b) => a + b, 0);
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b);
const keyMax = (o: Record<string, number>): string => Object.keys(o).reduce((a, b) => (o[b] > o[a] ? b : a));

// ---- 제약 카드: 예산 네 칸 (숫자는 이 코드를 위해 지어낸 값이라 수업 카드와 같지 않다)
const BUDGET_KEYS = ["모델(MB)", "RAM(MB)", "지연(초)", "명료도(CER%)"];
type Measured = Record<string, number>;
type Card = Measured & { name: string };
const CARDS: Record<string, Card> = {
  A: { name: "작은 저장 공간", "모델(MB)": 320, "RAM(MB)": 700, "지연(초)": 2.5, "명료도(CER%)": 20 },
  B: { name: "작은 메모리", "모델(MB)": 500, "RAM(MB)": 560, "지연(초)": 2.5, "명료도(CER%)": 20 },
  C: { name: "빠른 응답", "모델(MB)": 500, "RAM(MB)": 700, "지연(초)": 1.5, "명료도(CER%)": 20 },
  D: { name: "모두 빠듯", "모델(MB)": 330, "RAM(MB)": 600, "지연(초)": 1.7, "명료도(CER%)": 20 },
};

function violations(measured: Measured, card: Measured): string[] {
  // 예산을 넘은 칸의 이름. 같으면 넘지 않은 것이다
  return BUDGET_KEYS.filter((k) => measured[k] > card[k]);
}

function percentile(xs: number[], q: number): number {
  // 가까운 순위 방식 백분위수: 작은 것부터 줄 세워 k번째 값 (k = ceil(q/100 x 개수), 최소 1)
  const s = [...xs].sort((a, b) => a - b);
  const k = Math.max(1, Math.ceil((q * s.length) / 100));
  return s[k - 1];
}

function finalScore(func: number, nViol: number): number {
  // 예산을 하나라도 넘으면(하나든 셋이든) 기능 점수의 절반
  return roundHalfUp(nViol === 0 ? func : func * 0.5, 1);
}

// ---- 설계 열 가지와 예산을 재는 가상 저울 (실제 모델 대신 크기 · 시간 표를 쓴다)
interface Design {
  asr: string; threads: number; method: string; hotwords: string[]; endpoint: number;
  fuzzy: number; sv: string; sv_th: number; tts_steps: number; first_sentence: boolean;
}
const BASELINE: Design = { asr: "fp32", threads: 2, method: "greedy_search", hotwords: [], endpoint: 1.2, fuzzy: 0, sv: "campp", sv_th: 0.5, tts_steps: 8, first_sentence: false };
const ASR_MB: Record<string, number> = { fp32: 314.0, int8: 132.0 }; // 받아쓰기 모델 파일 크기
const SV_MB: Record<string, number> = { campp: 28.0, titanet: 40.0 }; // 화자 검증 모델 파일 크기
const TTS_MB = 144.0; // 말하기 모델
const ETC_MB = 1.8; // 나머지(어휘 · 설정)
const ASR_TAIL: Record<string, number> = { fp32: 0.16, int8: 0.11 }; // 받아쓰기 마무리 시간(초, 기준 기계 · 스레드 1개)
const SV_SEC: Record<string, number> = { campp: 0.05, titanet: 0.09 }; // 화자 검증 시간(초)
const CER_BY_STEPS = [92.0, 62.0, 41.0, 24.0, 14.0, 9.0, 7.5, 6.6, 6.4, 6.3, 6.2, 6.2]; // 말하기 단계 1~12의 명료도 CER(%)

function partsMb(d: Design): Record<string, number> {
  return { "받아쓰기": ASR_MB[d.asr], "말하기": TTS_MB, "화자 검증": SV_MB[d.sv], "기타": ETC_MB };
}

function modelMb(d: Design): number {
  return roundHalfUp(sum(Object.values(partsMb(d))), 1);
}

function ramMb(d: Design): number {
  const beam = d.method === "modified_beam_search" ? 25.0 : 0.0;
  return roundHalfUp(0.9 * modelMb(d) + 150 + 20 * d.threads + beam, 1);
}

function asrTail(d: Design): number {
  const beam = d.method === "modified_beam_search" ? 0.03 : 0.0;
  return ASR_TAIL[d.asr] / (1 + 0.3 * (d.threads - 1)) + beam;
}

function ttsTime(steps: number, chars: number): number {
  // 말하기 모델이 소리를 만드는 시간: 기본 시간 + 단계 x (글자 수에 비례)
  return 0.1 + steps * (0.02 + 0.0018 * chars);
}

function firstChunk(reply: string): string {
  // 답의 첫 문장만: 문장 끝 부호(. ? !) 뒤의 공백에서 나눈다
  return reply.trim().split(/(?<=[.?!])\s+/)[0];
}

function clarity(steps: number): number {
  return CER_BY_STEPS[steps - 1];
}

function latencyParts(d: Design, reply: string): Record<string, number> {
  // 말이 끝난 뒤 첫 소리까지의 네 단계(초)
  const text = d.first_sentence ? firstChunk(reply) : reply;
  return { "끝점 기다리기": d.endpoint, "받아쓰기 마무리": asrTail(d), "화자 검증": SV_SEC[d.sv], "첫 소리 만들기": ttsTime(d.tts_steps, text.length) };
}

// ---- 한글을 자모로 풀어 재는 편집 거리 (깨움말 · 용어 맞추기)
const CHO = Array.from("ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ");
const JUNG = Array.from("ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ");
const JONG = ["", "ㄱ", "ㄲ", "ㄳ", "ㄴ", "ㄵ", "ㄶ", "ㄷ", "ㄹ", "ㄺ", "ㄻ", "ㄼ", "ㄽ", "ㄾ", "ㄿ", "ㅀ", "ㅁ", "ㅂ", "ㅄ", "ㅅ", "ㅆ", "ㅇ", "ㅈ", "ㅊ", "ㅋ", "ㅌ", "ㅍ", "ㅎ"];

function jamo(text: string): string[] {
  const out: string[] = [];
  for (const ch of text) {
    const o = ch.codePointAt(0)! - 0xac00;
    if (o >= 0 && o < 11172) {
      out.push(CHO[Math.floor(o / 588)], JUNG[Math.floor((o % 588) / 28)]);
      if (o % 28) out.push(JONG[o % 28]);
    } else {
      out.push(ch);
    }
  }
  return out;
}

function jamoDist(a: string, b: string): number {
  const x = jamo(a);
  const y = jamo(b);
  const row = Array.from({ length: y.length + 1 }, (_, j) => j);
  for (let i = 1; i <= x.length; i++) {
    let prev = row[0];
    row[0] = i;
    for (let j = 1; j <= y.length; j++) {
      const cur = row[j];
      row[j] = Math.min(row[j] + 1, row[j - 1] + 1, prev + (x[i - 1] !== y[j - 1] ? 1 : 0));
      prev = cur;
    }
  }
  return row[y.length];
}

function heardWake(text: string, allowed: number): boolean {
  // 받아쓴 글의 앞 세 글자가 깨움말 '하나야'와 자모 거리 allowed 이내인가
  const t = text.replace(/[^0-9A-Za-z가-힣]/g, "");
  return jamoDist("하나야", t.slice(0, 3)) <= allowed;
}

// ---- 목소리: 코사인 유사도와 화자 검증 (임베딩은 모델 대신 난수 벡터에 소음을 섞어 흉내)
function cosine(a: number[], b: number[]): number {
  const dot = sum(a.map((x, i) => x * b[i]));
  return dot / (Math.sqrt(sum(a.map((x) => x * x))) * Math.sqrt(sum(b.map((y) => y * y))));
}

function who(emb: number[], enrolled: Record<string, number[]>, th: number): string | null {
  // 등록된 사람 가운데 가장 비슷한 이름. 유사도가 문턱값 미만이면 null
  let best: string | null = null;
  let score = -1.0;
  for (const [name, vec] of Object.entries(enrolled)) {
    const s = cosine(emb, vec);
    if (s > score) {
      best = name;
      score = s;
    }
  }
  return score >= th ? best : null;
}

function randList(seed: number, n: number): number[] {
  // 같은 seed면 늘 같은 -1 ~ 1 난수 n개 (Park-Miller, Python · TS가 똑같이 나온다)
  const out: number[] = [];
  let s = seed;
  for (let i = 0; i < n; i++) {
    s = (s * 48271) % 2147483647;
    out.push((s / 2147483647) * 2 - 1);
  }
  return out;
}

const DIM = 12;
const H = randList(11, DIM);
const D = randList(23, DIM);
const R31 = randList(31, DIM);
const VOICES: Record<string, number[]> = {
  "김하늘": H, "박도윤": D, "외부인1": H.map((h, i) => 0.25 * h + 0.75 * R31[i]),
  "외부인2": randList(47, DIM), "외부인3": randList(59, DIM),
};
const COMMON = randList(7, DIM); // 모든 목소리에 깔리는 공통 성분: campp는 이것이 커서 남남도 어느 정도 닮아 보인다
const SV_BIAS: Record<string, number> = { campp: 0.8, titanet: 0.0 };
const SV_NOISE: Record<string, number> = { campp: 0.6, titanet: 0.4 }; // titanet이 더 또렷하게 가른다 (대신 12 MB 더 큼)

function embed(model: string, voice: string, seed: number): number[] {
  const noise = randList(seed, DIM);
  return VOICES[voice].map((v, i) => v + SV_BIAS[model] * COMMON[i] + SV_NOISE[model] * noise[i]);
}

function enroll(model: string): Record<string, number[]> {
  // 작업자마다 등록 음성 2개의 평균 벡터
  const out: Record<string, number[]> = {};
  ["김하늘", "박도윤"].forEach((w, i) => {
    const a = embed(model, w, 1 + i * 2);
    const b = embed(model, w, 2 + i * 2);
    out[w] = a.map((x, k) => (x + b[k]) / 2);
  });
  return out;
}

// ---- 시나리오 15개: 말한 사람 · 기대하는 일 · 말 안의 가장 긴 쉼(초) · 받아쓴 글 (int8 · 핫워드 빔 탐색일 때 달라지는 것만 따로)
const EQUIP = ["펌프", "컨베이어", "보일러", "압축기"];
const INTENTS = ["마지막", "상태", "기록"];
interface Scene { id: string; voice: string; expect: string; pause: number; raw: string; int8?: string; hot?: string }
const SCENES: Scene[] = [
  { id: "S01", voice: "김하늘", expect: "status", pause: 0.12, raw: "하나야 3번 펌프 상태 알려 줘" },
  { id: "S02", voice: "박도윤", expect: "status", pause: 0.30, raw: "하나야 1번 보일러 상태 알려 줘" },
  { id: "S03", voice: "김하늘", expect: "status", pause: 0.18, raw: "하나야 2번 컴레이어 상태 알려 줘", hot: "하나야 2번 컨베이어 상태 알려 줘" },
  { id: "S04", voice: "박도윤", expect: "status", pause: 0.56, raw: "하나야 5번 압축기 상태 알려 줘" },
  { id: "S05", voice: "김하늘", expect: "record", pause: 0.15, raw: "하나에 5번 압축기 정지 기록해 줘" },
  { id: "S06", voice: "박도윤", expect: "record", pause: 0.52, raw: "하나야 1번 보일러 과일 이렇게 해 줘", hot: "하나야 1번 보일러 과열 기록해 줘" },
  { id: "S07", voice: "김하늘", expect: "record", pause: 0.20, raw: "하나야 3번 펌프 점검 완료 기록해 줘" },
  { id: "S08", voice: "박도윤", expect: "ignore", pause: 0.10, raw: "3번 펌프 상태 좀 봐" },
  { id: "S09", voice: "김하늘", expect: "ignore", pause: 0.14, raw: "오늘 점심은 뭐 먹지" },
  { id: "S10", voice: "외부인2", expect: "refuse", pause: 0.13, raw: "하나야 3번 펌프 상태 알려 줘" },
  { id: "S11", voice: "외부인1", expect: "refuse", pause: 0.16, raw: "하나야 1번 보일러 상태 알려 줘" },
  { id: "S12", voice: "외부인3", expect: "refuse", pause: 0.11, raw: "하나야 5번 압축기 정지 기록해 줘" },
  { id: "S13", voice: "김하늘", expect: "reask", pause: 0.17, raw: "하나야 4번 냉각기 상태 알려 줘" },
  { id: "S14", voice: "김하늘", expect: "status", pause: 0.19, raw: "하나야 3번 펌프 상태 알려 줘", int8: "하나야 3번 퍼프 상태 알려 줘" },
  { id: "S15", voice: "박도윤", expect: "last", pause: 0.14, raw: "하나야 마지막 기록 읽어 줘" },
];
const REPLIES: Record<string, string> = {
  status: "3번 펌프는 정상입니다. 계속 가동해도 됩니다.", record: "기록했습니다. 5번 압축기 정지입니다.", refuse: "등록된 작업자만 쓸 수 있습니다.",
  reask: "그 설비는 목록에 없습니다. 다시 말씀해 주세요.", last: "마지막 기록은 5번 압축기 정지입니다. 기록한 사람은 김하늘입니다.",
};

function find(words: string[], vocab: string[], fuzzy: number): string | null {
  // 낱말 앞부분과 사전 낱말의 자모 거리가 (음절 수 x fuzzy) 이하인 가장 가까운 사전 낱말
  let best: [number, string] | null = null;
  for (const w of vocab) {
    for (const t of words) {
      const dist = jamoDist(w, t.slice(0, w.length));
      if (dist <= w.length * fuzzy && (best === null || dist < best[0])) best = [dist, w];
    }
  }
  return best ? best[1] : null;
}

const words = (s: string): string[] => s.split(/\s+/).filter((w) => w.length > 0);

function handle(d: Design, s: Scene, idx: number, enrolled: Record<string, number[]>, log: [string, string][]): [string, string | null] {
  // 한 시나리오를 처리해 [결과, 기록자 이름]을 돌려준다. 결과: ignore · refuse · reask · status · record · last
  let heard = s.raw;
  if (d.method === "modified_beam_search" && d.hotwords.length > 0) heard = s.hot ?? heard;
  else if (d.asr === "int8") heard = s.int8 ?? heard;
  if (d.endpoint <= s.pause) heard = words(heard)[0]; // 말 중간의 쉼에서 끝났다고 보고 잘라 버린다
  if (!heardWake(heard, 3 * d.fuzzy)) return ["ignore", null];
  const name = who(embed(d.sv, s.voice, 200 + idx), enrolled, d.sv_th);
  if (name === null) return ["refuse", null];
  const rest = words(heard).slice(1);
  const intent = find(rest, INTENTS, d.fuzzy);
  const equip = find(rest, EQUIP, d.fuzzy);
  if (intent === "마지막") return log.length > 0 ? ["last", name] : ["reask", name];
  if (intent === null || equip === null) return ["reask", name];
  if (intent === "기록") {
    log.push([name, equip]);
    return ["record", name];
  }
  return ["status", name];
}

interface Row { id: string; voice: string; expect: string; result: string; name: string | null; ok: boolean; cut: boolean }
interface Result { rows: Row[]; passed: number; score: number; leaks: number }

function runScenarios(d: Design): Result {
  const enrolled = enroll(d.sv);
  const log: [string, string][] = [];
  const rows: Row[] = SCENES.map((s, i) => {
    const [result, name] = handle(d, s, i, enrolled, log);
    const ok = result === s.expect && (s.expect !== "record" || name === s.voice);
    return { id: s.id, voice: s.voice, expect: s.expect, result, name, ok, cut: d.endpoint <= s.pause };
  });
  const passed = rows.filter((r) => r.ok).length;
  const leaks = rows.filter((r) => r.voice.startsWith("외부인") && ["status", "record", "last"].includes(r.result)).length;
  return { rows, passed, score: roundHalfUp((passed / rows.length) * 100, 1), leaks };
}

function measure(d: Design, res: Result): { m: Measured; parts: Record<string, number>; lat: number[] } {
  // 예산 네 칸을 잰다. 지연은 소리로 답한 시나리오들의 중앙값(p50)
  const spoken = res.rows.filter((r) => r.result !== "ignore").map((r) => REPLIES[r.result]);
  const lat = spoken.map((t) => roundHalfUp(sum(Object.values(latencyParts(d, t))), 2));
  return { m: { "모델(MB)": modelMb(d), "RAM(MB)": ramMb(d), "지연(초)": percentile(lat, 50), "명료도(CER%)": clarity(d.tts_steps) }, parts: partsMb(d), lat };
}

const FRAME = 0.02; // 20 ms 조각

function energy(parts: [boolean, number][]): number[] {
  // (소리 있음/없음, 초) 토막들을 20 ms 조각마다 소리 크기 하나로: 소리 0.3, 쉼 0.0
  const out: number[] = [];
  for (const [loud, sec] of parts) out.push(...Array(Math.round(sec / FRAME)).fill(loud ? 0.3 : 0.0));
  return out;
}

function endpointCut(frames: number[], wait: number): [number, boolean] {
  // 조용한 조각이 wait초 이어지면 거기서 말이 끝났다고 보고 자른다. [자른 조각 수, 잘렸나]
  let quiet = 0;
  for (let i = 0; i < frames.length; i++) {
    quiet = frames[i] < 0.05 ? quiet + 1 : 0;
    if (quiet * FRAME >= wait - 1e-9) return [i + 1 - quiet, i + 1 < frames.length]; // 말 끝(조용해지기 직전)까지만 듣는다
  }
  return [frames.length, false];
}

// S04: "하나야" 쉼 "5번 압축기 상태 알려 줘" - 중간의 쉼이 0.56초
const s04 = energy([[true, 0.36], [false, 0.56], [true, 1.2]]);
for (const wait of [0.3, 0.5, 0.6, 1.2]) {
  const [n, cut] = endpointCut(s04, wait);
  console.log(`끝점 ${wait}초: 비서가 들은 길이 ${roundHalfUp(n * FRAME, 2)}초 / 전체 ${roundHalfUp(s04.length * FRAME, 2)}초 - ` + (cut ? "말 중간에서 잘림" : "끝까지 들음"));
}

const EP: { endpoint: number; p50: number; cut: string[]; passed: number }[] = [];
for (const ep of [0.3, 0.5, 0.6, 0.8, 1.2]) { // 값 하나만 바꾼다: 나머지는 같은 설계
  const d: Design = { ...BASELINE, asr: "int8", endpoint: ep };
  const res = runScenarios(d);
  const { m } = measure(d, res);
  const cut = res.rows.filter((r) => r.cut).map((r) => r.id);
  EP.push({ endpoint: ep, p50: m["지연(초)"], cut, passed: res.passed });
  console.log(`endpoint ${ep}: 지연 p50 ${m["지연(초)"]}초 - 잘린 발화 ${cut.length}개 ${cut.join(" ")} - 기능 통과 ${res.passed}`);
}
const SAFE_EP = Math.min(...EP.filter((e) => e.cut.length === 0).map((e) => e.endpoint));
const longest = Math.max(...SCENES.map((s) => s.pause));
console.log(`잘리지 않는 가장 짧은 값(시험한 것 가운데): ${SAFE_EP}초 - 말 안의 가장 긴 쉼: ${longest}초`);

const [n04, cut04] = endpointCut(s04, 0.3);
check(cut04 && roundHalfUp(n04 * FRAME, 2) === 0.36, "S04를 0.3초에서 끊으면 '하나야'(0.36초)까지만 듣고 잘려야 해요.");
check(!endpointCut(s04, 0.6)[1] && !endpointCut(s04, 1.2)[1], "쉼(0.56초)보다 길게 기다리면 잘리지 않아야 해요.");
check(EP[0].cut.length >= 2 && EP[EP.length - 1].cut.length === 0, "0.3초는 머뭇거리는 말이 2개 넘게 잘리고 1.2초는 하나도 안 잘려야 해요.");
check(EP[0].p50 < EP[EP.length - 1].p50 - 0.6, "끝점을 줄이면 지연이 0.6초 넘게 줄어야 해요.");
check(longest < SAFE_EP && SAFE_EP <= 0.8 && 0.5 <= SAFE_EP, "잘리지 않는 가장 짧은 값은 말 안의 가장 긴 쉼보다 길고 0.5 ~ 0.8초 사이여야 해요.");
check(EP[0].passed < EP[2].passed, "너무 줄인 끝점(0.3초)은 기능 통과가 줄어야 해요.");

steps.python:
# D50 · 말하기 단계와 명료도 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d50_steps.py   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 화자 검증 · 말하기 모델은 쓰지 않고 표와 규칙으로 흉내)
#   말하기 단계 줄이기: 빨라지지만 명료도에 낭떠러지가 있다. 잴 때마다 흔들리는 값은 여유를 두고 고르기 + 답의 첫 문장만 먼저
import math, re


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def round_half_up(x, nd=1):
    """반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)"""
    f = 10 ** nd
    return math.copysign(math.floor(abs(x) * f + 0.5) / f, x)


# ---- 제약 카드: 예산 네 칸 (숫자는 이 코드를 위해 지어낸 값이라 수업 카드와 같지 않다)
BUDGET_KEYS = ["모델(MB)", "RAM(MB)", "지연(초)", "명료도(CER%)"]
CARDS = {
    "A": {"name": "작은 저장 공간", "모델(MB)": 320, "RAM(MB)": 700, "지연(초)": 2.5, "명료도(CER%)": 20},
    "B": {"name": "작은 메모리", "모델(MB)": 500, "RAM(MB)": 560, "지연(초)": 2.5, "명료도(CER%)": 20},
    "C": {"name": "빠른 응답", "모델(MB)": 500, "RAM(MB)": 700, "지연(초)": 1.5, "명료도(CER%)": 20},
    "D": {"name": "모두 빠듯", "모델(MB)": 330, "RAM(MB)": 600, "지연(초)": 1.7, "명료도(CER%)": 20},
}


def violations(measured, card):
    """예산을 넘은 칸의 이름. 같으면 넘지 않은 것이다."""
    return [k for k in BUDGET_KEYS if measured[k] > card[k]]


def percentile(xs, q):
    """가까운 순위 방식 백분위수: 작은 것부터 줄 세워 k번째 값 (k = ceil(q/100 x 개수), 최소 1)."""
    s = sorted(xs)
    k = max(1, math.ceil(q * len(s) / 100))
    return s[k - 1]


def final_score(func, n_viol):
    """예산을 하나라도 넘으면(하나든 셋이든) 기능 점수의 절반."""
    return round_half_up(func if n_viol == 0 else func * 0.5, 1)


# ---- 설계 열 가지와 예산을 재는 가상 저울 (실제 모델 대신 크기 · 시간 표를 쓴다)
BASELINE = {"asr": "fp32", "threads": 2, "method": "greedy_search", "hotwords": [], "endpoint": 1.2, "fuzzy": 0,
            "sv": "campp", "sv_th": 0.5, "tts_steps": 8, "first_sentence": False}
ASR_MB = {"fp32": 314.0, "int8": 132.0}                   # 받아쓰기 모델 파일 크기
SV_MB = {"campp": 28.0, "titanet": 40.0}                  # 화자 검증 모델 파일 크기
TTS_MB, ETC_MB = 144.0, 1.8                               # 말하기 모델 · 나머지(어휘 · 설정)
ASR_TAIL = {"fp32": 0.16, "int8": 0.11}                   # 받아쓰기 마무리 시간(초, 기준 기계 · 스레드 1개)
SV_SEC = {"campp": 0.05, "titanet": 0.09}                 # 화자 검증 시간(초)
CER_BY_STEPS = [92.0, 62.0, 41.0, 24.0, 14.0, 9.0, 7.5, 6.6, 6.4, 6.3, 6.2, 6.2]   # 말하기 단계 1~12의 명료도 CER(%)


def parts_mb(d):
    return {"받아쓰기": ASR_MB[d["asr"]], "말하기": TTS_MB, "화자 검증": SV_MB[d["sv"]], "기타": ETC_MB}


def model_mb(d):
    return round_half_up(sum(parts_mb(d).values()), 1)


def ram_mb(d):
    beam = 25.0 if d["method"] == "modified_beam_search" else 0.0
    return round_half_up(0.9 * model_mb(d) + 150 + 20 * d["threads"] + beam, 1)


def asr_tail(d):
    beam = 0.03 if d["method"] == "modified_beam_search" else 0.0
    return ASR_TAIL[d["asr"]] / (1 + 0.3 * (d["threads"] - 1)) + beam


def tts_time(steps, chars):
    """말하기 모델이 소리를 만드는 시간: 기본 시간 + 단계 x (글자 수에 비례)."""
    return 0.10 + steps * (0.02 + 0.0018 * chars)


def first_chunk(reply):
    """답의 첫 문장만: 문장 끝 부호(. ? !) 뒤의 공백에서 나눈다."""
    return re.split(r"(?<=[.?!])\s+", reply.strip())[0]


def clarity(steps):
    return CER_BY_STEPS[steps - 1]


def latency_parts(d, reply):
    """말이 끝난 뒤 첫 소리까지의 네 단계(초)."""
    text = first_chunk(reply) if d["first_sentence"] else reply
    return {"끝점 기다리기": d["endpoint"], "받아쓰기 마무리": asr_tail(d), "화자 검증": SV_SEC[d["sv"]], "첫 소리 만들기": tts_time(d["tts_steps"], len(text))}


# ---- 한글을 자모로 풀어 재는 편집 거리 (깨움말 · 용어 맞추기)
CHO = "ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ"
JUNG = "ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ"
JONG = ["", "ㄱ", "ㄲ", "ㄳ", "ㄴ", "ㄵ", "ㄶ", "ㄷ", "ㄹ", "ㄺ", "ㄻ", "ㄼ", "ㄽ", "ㄾ", "ㄿ", "ㅀ", "ㅁ", "ㅂ", "ㅄ", "ㅅ", "ㅆ", "ㅇ", "ㅈ", "ㅊ", "ㅋ", "ㅌ", "ㅍ", "ㅎ"]


def jamo(text):
    out = []
    for ch in text:
        o = ord(ch) - 0xAC00
        if 0 <= o < 11172:
            out += [CHO[o // 588], JUNG[(o % 588) // 28]] + ([JONG[o % 28]] if o % 28 else [])
        else:
            out.append(ch)
    return out


def jamo_dist(a, b):
    x, y = jamo(a), jamo(b)
    row = list(range(len(y) + 1))
    for i in range(1, len(x) + 1):
        prev, row[0] = row[0], i
        for j in range(1, len(y) + 1):
            cur = row[j]
            row[j] = min(row[j] + 1, row[j - 1] + 1, prev + (x[i - 1] != y[j - 1]))
            prev = cur
    return row[len(y)]


def heard_wake(text, allowed):
    """받아쓴 글의 앞 세 글자가 깨움말 '하나야'와 자모 거리 allowed 이내인가."""
    t = re.sub(r"[^0-9A-Za-z가-힣]", "", text)
    return jamo_dist("하나야", t[:3]) <= allowed


# ---- 목소리: 코사인 유사도와 화자 검증 (임베딩은 모델 대신 난수 벡터에 소음을 섞어 흉내)
def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    return dot / (math.sqrt(sum(x * x for x in a)) * math.sqrt(sum(y * y for y in b)))


def who(emb, enrolled, th):
    """등록된 사람 가운데 가장 비슷한 이름. 유사도가 문턱값 미만이면 None."""
    best, score = None, -1.0
    for name, vec in enrolled.items():
        s = cosine(emb, vec)
        if s > score:
            best, score = name, s
    return best if score >= th else None


def rand_list(seed, n):
    """같은 seed면 늘 같은 -1 ~ 1 난수 n개 (Park-Miller, Python · TS가 똑같이 나온다)."""
    out, s = [], seed
    for _ in range(n):
        s = s * 48271 % 2147483647
        out.append(s / 2147483647 * 2 - 1)
    return out


DIM = 12
_H, _D = rand_list(11, DIM), rand_list(23, DIM)
VOICES = {"김하늘": _H, "박도윤": _D, "외부인1": [0.25 * h + 0.75 * r for h, r in zip(_H, rand_list(31, DIM))],
          "외부인2": rand_list(47, DIM), "외부인3": rand_list(59, DIM)}
COMMON = rand_list(7, DIM)                                # 모든 목소리에 깔리는 공통 성분: campp는 이것이 커서 남남도 어느 정도 닮아 보인다
SV_BIAS = {"campp": 0.8, "titanet": 0.0}
SV_NOISE = {"campp": 0.6, "titanet": 0.4}               # titanet이 더 또렷하게 가른다 (대신 12 MB 더 큼)


def embed(model, voice, seed):
    return [v + SV_BIAS[model] * c + SV_NOISE[model] * n for v, c, n in zip(VOICES[voice], COMMON, rand_list(seed, DIM))]


def enroll(model):
    """작업자마다 등록 음성 2개의 평균 벡터."""
    return {w: [(a + b) / 2 for a, b in zip(embed(model, w, 1 + i * 2), embed(model, w, 2 + i * 2))] for i, w in enumerate(["김하늘", "박도윤"])}


# ---- 시나리오 15개: 말한 사람 · 기대하는 일 · 말 안의 가장 긴 쉼(초) · 받아쓴 글 (int8 · 핫워드 빔 탐색일 때 달라지는 것만 따로)
EQUIP = ["펌프", "컨베이어", "보일러", "압축기"]
INTENTS = ["마지막", "상태", "기록"]
SCENES = [
    {"id": "S01", "voice": "김하늘", "expect": "status", "pause": 0.12, "raw": "하나야 3번 펌프 상태 알려 줘"},
    {"id": "S02", "voice": "박도윤", "expect": "status", "pause": 0.30, "raw": "하나야 1번 보일러 상태 알려 줘"},
    {"id": "S03", "voice": "김하늘", "expect": "status", "pause": 0.18, "raw": "하나야 2번 컴레이어 상태 알려 줘", "hot": "하나야 2번 컨베이어 상태 알려 줘"},
    {"id": "S04", "voice": "박도윤", "expect": "status", "pause": 0.56, "raw": "하나야 5번 압축기 상태 알려 줘"},
    {"id": "S05", "voice": "김하늘", "expect": "record", "pause": 0.15, "raw": "하나에 5번 압축기 정지 기록해 줘"},
    {"id": "S06", "voice": "박도윤", "expect": "record", "pause": 0.52, "raw": "하나야 1번 보일러 과일 이렇게 해 줘", "hot": "하나야 1번 보일러 과열 기록해 줘"},
    {"id": "S07", "voice": "김하늘", "expect": "record", "pause": 0.20, "raw": "하나야 3번 펌프 점검 완료 기록해 줘"},
    {"id": "S08", "voice": "박도윤", "expect": "ignore", "pause": 0.10, "raw": "3번 펌프 상태 좀 봐"},
    {"id": "S09", "voice": "김하늘", "expect": "ignore", "pause": 0.14, "raw": "오늘 점심은 뭐 먹지"},
    {"id": "S10", "voice": "외부인2", "expect": "refuse", "pause": 0.13, "raw": "하나야 3번 펌프 상태 알려 줘"},
    {"id": "S11", "voice": "외부인1", "expect": "refuse", "pause": 0.16, "raw": "하나야 1번 보일러 상태 알려 줘"},
    {"id": "S12", "voice": "외부인3", "expect": "refuse", "pause": 0.11, "raw": "하나야 5번 압축기 정지 기록해 줘"},
    {"id": "S13", "voice": "김하늘", "expect": "reask", "pause": 0.17, "raw": "하나야 4번 냉각기 상태 알려 줘"},
    {"id": "S14", "voice": "김하늘", "expect": "status", "pause": 0.19, "raw": "하나야 3번 펌프 상태 알려 줘", "int8": "하나야 3번 퍼프 상태 알려 줘"},
    {"id": "S15", "voice": "박도윤", "expect": "last", "pause": 0.14, "raw": "하나야 마지막 기록 읽어 줘"},
]
REPLIES = {"status": "3번 펌프는 정상입니다. 계속 가동해도 됩니다.", "record": "기록했습니다. 5번 압축기 정지입니다.", "refuse": "등록된 작업자만 쓸 수 있습니다.",
           "reask": "그 설비는 목록에 없습니다. 다시 말씀해 주세요.", "last": "마지막 기록은 5번 압축기 정지입니다. 기록한 사람은 김하늘입니다."}


def find(words, vocab, fuzzy):
    """낱말 앞부분과 사전 낱말의 자모 거리가 (음절 수 x fuzzy) 이하인 가장 가까운 사전 낱말."""
    best = None
    for w in vocab:
        for t in words:
            dist = jamo_dist(w, t[:len(w)])
            if dist <= len(w) * fuzzy and (best is None or dist < best[0]):
                best = (dist, w)
    return best[1] if best else None


def handle(d, s, idx, enrolled, log):
    """한 시나리오를 처리해 (결과, 기록자 이름)을 돌려준다. 결과: ignore · refuse · reask · status · record · last"""
    heard = s["raw"]
    if d["method"] == "modified_beam_search" and d["hotwords"]:
        heard = s.get("hot", heard)
    elif d["asr"] == "int8":
        heard = s.get("int8", heard)
    if d["endpoint"] <= s["pause"]:                       # 말 중간의 쉼에서 끝났다고 보고 잘라 버린다
        heard = heard.split()[0]
    if not heard_wake(heard, 3 * d["fuzzy"]):
        return "ignore", None
    name = who(embed(d["sv"], s["voice"], 200 + idx), enrolled, d["sv_th"])
    if name is None:
        return "refuse", None
    words = heard.split()[1:]
    intent, equip = find(words, INTENTS, d["fuzzy"]), find(words, EQUIP, d["fuzzy"])
    if intent == "마지막":
        return ("last", name) if log else ("reask", name)
    if intent is None or equip is None:
        return "reask", name
    if intent == "기록":
        log.append((name, equip))
        return "record", name
    return "status", name


def run_scenarios(d):
    enrolled, log, rows = enroll(d["sv"]), [], []
    for i, s in enumerate(SCENES):
        result, name = handle(d, s, i, enrolled, log)
        ok = result == s["expect"] and (s["expect"] != "record" or name == s["voice"])
        rows.append({"id": s["id"], "voice": s["voice"], "expect": s["expect"], "result": result, "name": name, "ok": ok, "cut": d["endpoint"] <= s["pause"]})
    passed = sum(r["ok"] for r in rows)
    leaks = sum(1 for r in rows if r["voice"].startswith("외부인") and r["result"] in ("status", "record", "last"))
    return {"rows": rows, "passed": passed, "score": round_half_up(passed / len(rows) * 100, 1), "leaks": leaks}


def measure(d, res):
    """예산 네 칸을 잰다. 지연은 소리로 답한 시나리오들의 중앙값(p50)."""
    spoken = [REPLIES[r["result"]] for r in res["rows"] if r["result"] != "ignore"]
    lat = [round_half_up(sum(latency_parts(d, t).values()), 2) for t in spoken]
    return {"모델(MB)": model_mb(d), "RAM(MB)": ram_mb(d), "지연(초)": percentile(lat, 50), "명료도(CER%)": clarity(d["tts_steps"]), "부품": parts_mb(d), "lat": lat}


SAMPLE = "1번 보일러는 과열 경고 상태입니다."
ST = []
for steps in [2, 4, 6, 8]:
    t = tts_time(steps, len(SAMPLE))
    ST.append({"steps": steps, "sec": round_half_up(t, 2), "cer": clarity(steps)})
    print(f"tts_steps={steps}: 만드는 시간 {round_half_up(t, 2)}초 - 명료도 CER {clarity(steps)}% - 예산(20% 이하) {'통과' if clarity(steps) <= 20 else '초과'}")
d86, d64, d42 = [ST[2]["cer"] - ST[3]["cer"], ST[1]["cer"] - ST[2]["cer"], ST[0]["cer"] - ST[1]["cer"]]   # 단계를 줄일 때마다 CER이 얼마나 나빠지나
print(f"CER 나빠지는 폭: 8->6 {round_half_up(d86, 1)} - 6->4 {round_half_up(d64, 1)} - 4->2 {round_half_up(d42, 1)} (낭떠러지)")


def measured_cer(steps, seed):
    """잴 때마다 조금 다른 값: 이 모델은 소리를 만들 때마다 무작위 값에서 출발한다. 경계(4 ~ 5단계) 근처일수록 크게 흔들린다."""
    wobble = 3.0 if steps in (4, 5) else 0.4
    return clarity(steps) + wobble * rand_list(seed * 7919, 4)[3]


worst = {s: max(measured_cer(s, 1000 + k) for k in range(20)) for s in range(3, 9)}
print("20번 잰 가장 나쁜 값:", {s: round_half_up(v, 1) for s, v in worst.items()})
safe = min(s for s in worst if worst[s] <= 20 - 5)         # 예산(20%)에서 5%p 여유를 두고 고른다
print(f"여유를 두고 고른 단계: {safe} (처음 한 번 잰 값이 예산 안이어도 흔들림까지 보고 고른다)")
edge_once = [round_half_up(measured_cer(4, k), 1) for k in (1, 2, 3, 4, 5, 6)]
print("4단계를 여섯 번 재면:", edge_once, "-> 잴 때마다 다르다")

# 답의 첫 문장만 먼저 소리로 만들면 첫 소리가 빨라진다
whole = "5번 압축기는 정지 상태입니다. 다시 켜기 전에 점검하세요."
first = first_chunk(whole)
t_whole, t_first = tts_time(6, len(whole)), tts_time(6, len(first))
print(f"첫 문장: '{first}' - 답 전체 {round_half_up(t_whole, 2)}초 / 첫 문장만 {round_half_up(t_first, 2)}초 (6단계)")

check(ST[0]["cer"] > 50 and ST[-1]["cer"] <= 20 and ST[0]["sec"] < ST[-1]["sec"], "2단계는 뭉개지고(CER 50% 초과) 8단계는 예산 안이며, 단계를 줄이면 빨라져야 해요.")
check(d42 > 3 * d86 and d64 > d86, "품질은 고르게 떨어지지 않아요: 4->2에서 8->6보다 3배 넘게 무너져야 해요.")
check(max(edge_once) > min(edge_once) and safe in (6, 7, 8) and worst[4] > clarity(4), "경계 근처(4단계)는 잴 때마다 값이 달라 여유 있는 6단계 이상을 골라야 해요.")
check(first_chunk("1번 보일러는 과열 경고 상태입니다. 가까이 가지 마세요.") == "1번 보일러는 과열 경고 상태입니다." and first_chunk(" 3번 펌프는 정상입니다. ") == "3번 펌프는 정상입니다.",
      "첫 문장만 돌려주고, 문장이 하나면 앞뒤 공백만 떼고 그대로 줘야 해요.")
check(t_first < t_whole and t_first > t_whole / 2, "첫 문장만 만들면 빨라지지만 절반까지는 안 줄어야 해요(기본 시간이 있어서).")

steps.typescript:
// D50 · 말하기 단계와 명료도 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d50_steps.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 화자 검증 · 말하기 모델은 쓰지 않고 표와 규칙으로 흉내)
//   말하기 단계 줄이기: 빨라지지만 명료도에 낭떠러지가 있다. 잴 때마다 흔들리는 값은 여유를 두고 고르기 + 답의 첫 문장만 먼저
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

const sum = (xs: number[]): number => xs.reduce((a, b) => a + b, 0);
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b);
const keyMax = (o: Record<string, number>): string => Object.keys(o).reduce((a, b) => (o[b] > o[a] ? b : a));

// ---- 제약 카드: 예산 네 칸 (숫자는 이 코드를 위해 지어낸 값이라 수업 카드와 같지 않다)
const BUDGET_KEYS = ["모델(MB)", "RAM(MB)", "지연(초)", "명료도(CER%)"];
type Measured = Record<string, number>;
type Card = Measured & { name: string };
const CARDS: Record<string, Card> = {
  A: { name: "작은 저장 공간", "모델(MB)": 320, "RAM(MB)": 700, "지연(초)": 2.5, "명료도(CER%)": 20 },
  B: { name: "작은 메모리", "모델(MB)": 500, "RAM(MB)": 560, "지연(초)": 2.5, "명료도(CER%)": 20 },
  C: { name: "빠른 응답", "모델(MB)": 500, "RAM(MB)": 700, "지연(초)": 1.5, "명료도(CER%)": 20 },
  D: { name: "모두 빠듯", "모델(MB)": 330, "RAM(MB)": 600, "지연(초)": 1.7, "명료도(CER%)": 20 },
};

function violations(measured: Measured, card: Measured): string[] {
  // 예산을 넘은 칸의 이름. 같으면 넘지 않은 것이다
  return BUDGET_KEYS.filter((k) => measured[k] > card[k]);
}

function percentile(xs: number[], q: number): number {
  // 가까운 순위 방식 백분위수: 작은 것부터 줄 세워 k번째 값 (k = ceil(q/100 x 개수), 최소 1)
  const s = [...xs].sort((a, b) => a - b);
  const k = Math.max(1, Math.ceil((q * s.length) / 100));
  return s[k - 1];
}

function finalScore(func: number, nViol: number): number {
  // 예산을 하나라도 넘으면(하나든 셋이든) 기능 점수의 절반
  return roundHalfUp(nViol === 0 ? func : func * 0.5, 1);
}

// ---- 설계 열 가지와 예산을 재는 가상 저울 (실제 모델 대신 크기 · 시간 표를 쓴다)
interface Design {
  asr: string; threads: number; method: string; hotwords: string[]; endpoint: number;
  fuzzy: number; sv: string; sv_th: number; tts_steps: number; first_sentence: boolean;
}
const BASELINE: Design = { asr: "fp32", threads: 2, method: "greedy_search", hotwords: [], endpoint: 1.2, fuzzy: 0, sv: "campp", sv_th: 0.5, tts_steps: 8, first_sentence: false };
const ASR_MB: Record<string, number> = { fp32: 314.0, int8: 132.0 }; // 받아쓰기 모델 파일 크기
const SV_MB: Record<string, number> = { campp: 28.0, titanet: 40.0 }; // 화자 검증 모델 파일 크기
const TTS_MB = 144.0; // 말하기 모델
const ETC_MB = 1.8; // 나머지(어휘 · 설정)
const ASR_TAIL: Record<string, number> = { fp32: 0.16, int8: 0.11 }; // 받아쓰기 마무리 시간(초, 기준 기계 · 스레드 1개)
const SV_SEC: Record<string, number> = { campp: 0.05, titanet: 0.09 }; // 화자 검증 시간(초)
const CER_BY_STEPS = [92.0, 62.0, 41.0, 24.0, 14.0, 9.0, 7.5, 6.6, 6.4, 6.3, 6.2, 6.2]; // 말하기 단계 1~12의 명료도 CER(%)

function partsMb(d: Design): Record<string, number> {
  return { "받아쓰기": ASR_MB[d.asr], "말하기": TTS_MB, "화자 검증": SV_MB[d.sv], "기타": ETC_MB };
}

function modelMb(d: Design): number {
  return roundHalfUp(sum(Object.values(partsMb(d))), 1);
}

function ramMb(d: Design): number {
  const beam = d.method === "modified_beam_search" ? 25.0 : 0.0;
  return roundHalfUp(0.9 * modelMb(d) + 150 + 20 * d.threads + beam, 1);
}

function asrTail(d: Design): number {
  const beam = d.method === "modified_beam_search" ? 0.03 : 0.0;
  return ASR_TAIL[d.asr] / (1 + 0.3 * (d.threads - 1)) + beam;
}

function ttsTime(steps: number, chars: number): number {
  // 말하기 모델이 소리를 만드는 시간: 기본 시간 + 단계 x (글자 수에 비례)
  return 0.1 + steps * (0.02 + 0.0018 * chars);
}

function firstChunk(reply: string): string {
  // 답의 첫 문장만: 문장 끝 부호(. ? !) 뒤의 공백에서 나눈다
  return reply.trim().split(/(?<=[.?!])\s+/)[0];
}

function clarity(steps: number): number {
  return CER_BY_STEPS[steps - 1];
}

function latencyParts(d: Design, reply: string): Record<string, number> {
  // 말이 끝난 뒤 첫 소리까지의 네 단계(초)
  const text = d.first_sentence ? firstChunk(reply) : reply;
  return { "끝점 기다리기": d.endpoint, "받아쓰기 마무리": asrTail(d), "화자 검증": SV_SEC[d.sv], "첫 소리 만들기": ttsTime(d.tts_steps, text.length) };
}

// ---- 한글을 자모로 풀어 재는 편집 거리 (깨움말 · 용어 맞추기)
const CHO = Array.from("ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ");
const JUNG = Array.from("ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ");
const JONG = ["", "ㄱ", "ㄲ", "ㄳ", "ㄴ", "ㄵ", "ㄶ", "ㄷ", "ㄹ", "ㄺ", "ㄻ", "ㄼ", "ㄽ", "ㄾ", "ㄿ", "ㅀ", "ㅁ", "ㅂ", "ㅄ", "ㅅ", "ㅆ", "ㅇ", "ㅈ", "ㅊ", "ㅋ", "ㅌ", "ㅍ", "ㅎ"];

function jamo(text: string): string[] {
  const out: string[] = [];
  for (const ch of text) {
    const o = ch.codePointAt(0)! - 0xac00;
    if (o >= 0 && o < 11172) {
      out.push(CHO[Math.floor(o / 588)], JUNG[Math.floor((o % 588) / 28)]);
      if (o % 28) out.push(JONG[o % 28]);
    } else {
      out.push(ch);
    }
  }
  return out;
}

function jamoDist(a: string, b: string): number {
  const x = jamo(a);
  const y = jamo(b);
  const row = Array.from({ length: y.length + 1 }, (_, j) => j);
  for (let i = 1; i <= x.length; i++) {
    let prev = row[0];
    row[0] = i;
    for (let j = 1; j <= y.length; j++) {
      const cur = row[j];
      row[j] = Math.min(row[j] + 1, row[j - 1] + 1, prev + (x[i - 1] !== y[j - 1] ? 1 : 0));
      prev = cur;
    }
  }
  return row[y.length];
}

function heardWake(text: string, allowed: number): boolean {
  // 받아쓴 글의 앞 세 글자가 깨움말 '하나야'와 자모 거리 allowed 이내인가
  const t = text.replace(/[^0-9A-Za-z가-힣]/g, "");
  return jamoDist("하나야", t.slice(0, 3)) <= allowed;
}

// ---- 목소리: 코사인 유사도와 화자 검증 (임베딩은 모델 대신 난수 벡터에 소음을 섞어 흉내)
function cosine(a: number[], b: number[]): number {
  const dot = sum(a.map((x, i) => x * b[i]));
  return dot / (Math.sqrt(sum(a.map((x) => x * x))) * Math.sqrt(sum(b.map((y) => y * y))));
}

function who(emb: number[], enrolled: Record<string, number[]>, th: number): string | null {
  // 등록된 사람 가운데 가장 비슷한 이름. 유사도가 문턱값 미만이면 null
  let best: string | null = null;
  let score = -1.0;
  for (const [name, vec] of Object.entries(enrolled)) {
    const s = cosine(emb, vec);
    if (s > score) {
      best = name;
      score = s;
    }
  }
  return score >= th ? best : null;
}

function randList(seed: number, n: number): number[] {
  // 같은 seed면 늘 같은 -1 ~ 1 난수 n개 (Park-Miller, Python · TS가 똑같이 나온다)
  const out: number[] = [];
  let s = seed;
  for (let i = 0; i < n; i++) {
    s = (s * 48271) % 2147483647;
    out.push((s / 2147483647) * 2 - 1);
  }
  return out;
}

const DIM = 12;
const H = randList(11, DIM);
const D = randList(23, DIM);
const R31 = randList(31, DIM);
const VOICES: Record<string, number[]> = {
  "김하늘": H, "박도윤": D, "외부인1": H.map((h, i) => 0.25 * h + 0.75 * R31[i]),
  "외부인2": randList(47, DIM), "외부인3": randList(59, DIM),
};
const COMMON = randList(7, DIM); // 모든 목소리에 깔리는 공통 성분: campp는 이것이 커서 남남도 어느 정도 닮아 보인다
const SV_BIAS: Record<string, number> = { campp: 0.8, titanet: 0.0 };
const SV_NOISE: Record<string, number> = { campp: 0.6, titanet: 0.4 }; // titanet이 더 또렷하게 가른다 (대신 12 MB 더 큼)

function embed(model: string, voice: string, seed: number): number[] {
  const noise = randList(seed, DIM);
  return VOICES[voice].map((v, i) => v + SV_BIAS[model] * COMMON[i] + SV_NOISE[model] * noise[i]);
}

function enroll(model: string): Record<string, number[]> {
  // 작업자마다 등록 음성 2개의 평균 벡터
  const out: Record<string, number[]> = {};
  ["김하늘", "박도윤"].forEach((w, i) => {
    const a = embed(model, w, 1 + i * 2);
    const b = embed(model, w, 2 + i * 2);
    out[w] = a.map((x, k) => (x + b[k]) / 2);
  });
  return out;
}

// ---- 시나리오 15개: 말한 사람 · 기대하는 일 · 말 안의 가장 긴 쉼(초) · 받아쓴 글 (int8 · 핫워드 빔 탐색일 때 달라지는 것만 따로)
const EQUIP = ["펌프", "컨베이어", "보일러", "압축기"];
const INTENTS = ["마지막", "상태", "기록"];
interface Scene { id: string; voice: string; expect: string; pause: number; raw: string; int8?: string; hot?: string }
const SCENES: Scene[] = [
  { id: "S01", voice: "김하늘", expect: "status", pause: 0.12, raw: "하나야 3번 펌프 상태 알려 줘" },
  { id: "S02", voice: "박도윤", expect: "status", pause: 0.30, raw: "하나야 1번 보일러 상태 알려 줘" },
  { id: "S03", voice: "김하늘", expect: "status", pause: 0.18, raw: "하나야 2번 컴레이어 상태 알려 줘", hot: "하나야 2번 컨베이어 상태 알려 줘" },
  { id: "S04", voice: "박도윤", expect: "status", pause: 0.56, raw: "하나야 5번 압축기 상태 알려 줘" },
  { id: "S05", voice: "김하늘", expect: "record", pause: 0.15, raw: "하나에 5번 압축기 정지 기록해 줘" },
  { id: "S06", voice: "박도윤", expect: "record", pause: 0.52, raw: "하나야 1번 보일러 과일 이렇게 해 줘", hot: "하나야 1번 보일러 과열 기록해 줘" },
  { id: "S07", voice: "김하늘", expect: "record", pause: 0.20, raw: "하나야 3번 펌프 점검 완료 기록해 줘" },
  { id: "S08", voice: "박도윤", expect: "ignore", pause: 0.10, raw: "3번 펌프 상태 좀 봐" },
  { id: "S09", voice: "김하늘", expect: "ignore", pause: 0.14, raw: "오늘 점심은 뭐 먹지" },
  { id: "S10", voice: "외부인2", expect: "refuse", pause: 0.13, raw: "하나야 3번 펌프 상태 알려 줘" },
  { id: "S11", voice: "외부인1", expect: "refuse", pause: 0.16, raw: "하나야 1번 보일러 상태 알려 줘" },
  { id: "S12", voice: "외부인3", expect: "refuse", pause: 0.11, raw: "하나야 5번 압축기 정지 기록해 줘" },
  { id: "S13", voice: "김하늘", expect: "reask", pause: 0.17, raw: "하나야 4번 냉각기 상태 알려 줘" },
  { id: "S14", voice: "김하늘", expect: "status", pause: 0.19, raw: "하나야 3번 펌프 상태 알려 줘", int8: "하나야 3번 퍼프 상태 알려 줘" },
  { id: "S15", voice: "박도윤", expect: "last", pause: 0.14, raw: "하나야 마지막 기록 읽어 줘" },
];
const REPLIES: Record<string, string> = {
  status: "3번 펌프는 정상입니다. 계속 가동해도 됩니다.", record: "기록했습니다. 5번 압축기 정지입니다.", refuse: "등록된 작업자만 쓸 수 있습니다.",
  reask: "그 설비는 목록에 없습니다. 다시 말씀해 주세요.", last: "마지막 기록은 5번 압축기 정지입니다. 기록한 사람은 김하늘입니다.",
};

function find(words: string[], vocab: string[], fuzzy: number): string | null {
  // 낱말 앞부분과 사전 낱말의 자모 거리가 (음절 수 x fuzzy) 이하인 가장 가까운 사전 낱말
  let best: [number, string] | null = null;
  for (const w of vocab) {
    for (const t of words) {
      const dist = jamoDist(w, t.slice(0, w.length));
      if (dist <= w.length * fuzzy && (best === null || dist < best[0])) best = [dist, w];
    }
  }
  return best ? best[1] : null;
}

const words = (s: string): string[] => s.split(/\s+/).filter((w) => w.length > 0);

function handle(d: Design, s: Scene, idx: number, enrolled: Record<string, number[]>, log: [string, string][]): [string, string | null] {
  // 한 시나리오를 처리해 [결과, 기록자 이름]을 돌려준다. 결과: ignore · refuse · reask · status · record · last
  let heard = s.raw;
  if (d.method === "modified_beam_search" && d.hotwords.length > 0) heard = s.hot ?? heard;
  else if (d.asr === "int8") heard = s.int8 ?? heard;
  if (d.endpoint <= s.pause) heard = words(heard)[0]; // 말 중간의 쉼에서 끝났다고 보고 잘라 버린다
  if (!heardWake(heard, 3 * d.fuzzy)) return ["ignore", null];
  const name = who(embed(d.sv, s.voice, 200 + idx), enrolled, d.sv_th);
  if (name === null) return ["refuse", null];
  const rest = words(heard).slice(1);
  const intent = find(rest, INTENTS, d.fuzzy);
  const equip = find(rest, EQUIP, d.fuzzy);
  if (intent === "마지막") return log.length > 0 ? ["last", name] : ["reask", name];
  if (intent === null || equip === null) return ["reask", name];
  if (intent === "기록") {
    log.push([name, equip]);
    return ["record", name];
  }
  return ["status", name];
}

interface Row { id: string; voice: string; expect: string; result: string; name: string | null; ok: boolean; cut: boolean }
interface Result { rows: Row[]; passed: number; score: number; leaks: number }

function runScenarios(d: Design): Result {
  const enrolled = enroll(d.sv);
  const log: [string, string][] = [];
  const rows: Row[] = SCENES.map((s, i) => {
    const [result, name] = handle(d, s, i, enrolled, log);
    const ok = result === s.expect && (s.expect !== "record" || name === s.voice);
    return { id: s.id, voice: s.voice, expect: s.expect, result, name, ok, cut: d.endpoint <= s.pause };
  });
  const passed = rows.filter((r) => r.ok).length;
  const leaks = rows.filter((r) => r.voice.startsWith("외부인") && ["status", "record", "last"].includes(r.result)).length;
  return { rows, passed, score: roundHalfUp((passed / rows.length) * 100, 1), leaks };
}

function measure(d: Design, res: Result): { m: Measured; parts: Record<string, number>; lat: number[] } {
  // 예산 네 칸을 잰다. 지연은 소리로 답한 시나리오들의 중앙값(p50)
  const spoken = res.rows.filter((r) => r.result !== "ignore").map((r) => REPLIES[r.result]);
  const lat = spoken.map((t) => roundHalfUp(sum(Object.values(latencyParts(d, t))), 2));
  return { m: { "모델(MB)": modelMb(d), "RAM(MB)": ramMb(d), "지연(초)": percentile(lat, 50), "명료도(CER%)": clarity(d.tts_steps) }, parts: partsMb(d), lat };
}

const SAMPLE = "1번 보일러는 과열 경고 상태입니다.";
const ST: { steps: number; sec: number; cer: number }[] = [];
for (const steps of [2, 4, 6, 8]) {
  const t = ttsTime(steps, SAMPLE.length);
  ST.push({ steps, sec: roundHalfUp(t, 2), cer: clarity(steps) });
  console.log(`tts_steps=${steps}: 만드는 시간 ${roundHalfUp(t, 2)}초 - 명료도 CER ${clarity(steps)}% - 예산(20% 이하) ${clarity(steps) <= 20 ? "통과" : "초과"}`);
}
const d86 = ST[2].cer - ST[3].cer; // 단계를 줄일 때마다 CER이 얼마나 나빠지나
const d64 = ST[1].cer - ST[2].cer;
const d42 = ST[0].cer - ST[1].cer;
console.log(`CER 나빠지는 폭: 8->6 ${roundHalfUp(d86, 1)} - 6->4 ${roundHalfUp(d64, 1)} - 4->2 ${roundHalfUp(d42, 1)} (낭떠러지)`);

function measuredCer(steps: number, seed: number): number {
  // 잴 때마다 조금 다른 값: 이 모델은 소리를 만들 때마다 무작위 값에서 출발한다. 경계(4 ~ 5단계) 근처일수록 크게 흔들린다
  const wobble = steps === 4 || steps === 5 ? 3.0 : 0.4;
  return clarity(steps) + wobble * randList(seed * 7919, 4)[3];
}

const worst: Record<number, number> = {};
for (let s = 3; s <= 8; s++) worst[s] = Math.max(...Array.from({ length: 20 }, (_, k) => measuredCer(s, 1000 + k)));
console.log("20번 잰 가장 나쁜 값:", JSON.stringify(Object.fromEntries(Object.entries(worst).map(([s, v]) => [s, roundHalfUp(v, 1)]))));
const safe = Math.min(...Object.keys(worst).map(Number).filter((s) => worst[s] <= 20 - 5)); // 예산(20%)에서 5%p 여유를 두고 고른다
console.log(`여유를 두고 고른 단계: ${safe} (처음 한 번 잰 값이 예산 안이어도 흔들림까지 보고 고른다)`);
const edgeOnce = [1, 2, 3, 4, 5, 6].map((k) => roundHalfUp(measuredCer(4, k), 1));
console.log("4단계를 여섯 번 재면:", JSON.stringify(edgeOnce), "-> 잴 때마다 다르다");

// 답의 첫 문장만 먼저 소리로 만들면 첫 소리가 빨라진다
const whole = "5번 압축기는 정지 상태입니다. 다시 켜기 전에 점검하세요.";
const first = firstChunk(whole);
const tWhole = ttsTime(6, whole.length);
const tFirst = ttsTime(6, first.length);
console.log(`첫 문장: '${first}' - 답 전체 ${roundHalfUp(tWhole, 2)}초 / 첫 문장만 ${roundHalfUp(tFirst, 2)}초 (6단계)`);

check(ST[0].cer > 50 && ST[ST.length - 1].cer <= 20 && ST[0].sec < ST[ST.length - 1].sec, "2단계는 뭉개지고(CER 50% 초과) 8단계는 예산 안이며, 단계를 줄이면 빨라져야 해요.");
check(d42 > 3 * d86 && d64 > d86, "품질은 고르게 떨어지지 않아요: 4->2에서 8->6보다 3배 넘게 무너져야 해요.");
check(Math.max(...edgeOnce) > Math.min(...edgeOnce) && [6, 7, 8].includes(safe) && worst[4] > clarity(4), "경계 근처(4단계)는 잴 때마다 값이 달라 여유 있는 6단계 이상을 골라야 해요.");
check(firstChunk("1번 보일러는 과열 경고 상태입니다. 가까이 가지 마세요.") === "1번 보일러는 과열 경고 상태입니다." && firstChunk(" 3번 펌프는 정상입니다. ") === "3번 펌프는 정상입니다.",
  "첫 문장만 돌려주고, 문장이 하나면 앞뒤 공백만 떼고 그대로 줘야 해요.");
check(tFirst < tWhole && tFirst > tWhole / 2, "첫 문장만 만들면 빨라지지만 절반까지는 안 줄어야 해요(기본 시간이 있어서).");

