}
const best = FZ.reduce((a, b) => (b.passed > a.passed ? b : a));
const overWrong: Record<string, [string, string]> = {};
for (const r of runScenarios({ ...LAB, fuzzy: 2 }).rows) if (!r.ok) overWrong[r.id] = [r.expect, r.result];
console.log("fuzzy=2에서 새로 틀린 것(기대, 결과):", JSON.stringify(overWrong));

const HOT = ["하나야", "펌프", "컨베이어", "보일러", "압축기", "상태", "기록", "점검 완료", "정지", "과열", "마지막"];
const DEC: { label: string; passed: number; ram: number; p50: number }[] = [];
const modes: [string, Partial<Design>][] = [["탐욕", {}], ["빔 탐색", { method: "modified_beam_search" }], ["빔 탐색 + 핫워드", { method: "modified_beam_search", hotwords: HOT }]];
for (const [label, extra] of modes) {
  const d: Design = { ...LAB, fuzzy: 1, ...extra };
  const res = runScenarios(d);
  const { m } = measure(d, res);
  DEC.push({ label, passed: res.passed, ram: m["RAM(MB)"], p50: m["지연(초)"] });
  console.log(`${label}: 기능 통과 ${res.passed} - RAM ${m["RAM(MB)"]} MB - 지연 p50 ${m["지연(초)"]}초`);
}
const s06 = SCENES.find((s) => s.id === "S06")!;
console.log("S06 받아쓴 글 (그냥 / 핫워드):", s06.raw, "/", s06.hot);

